/* Ego Tweaks — tweak list shown on the site (names, descriptions and plans only), generated from the 3.0 app catalog. */
window.EGO_SITE_CATALOG = {"version":"3.0.3","tiers":[{"n":0,"id":"free","name":"Free","price":0},{"n":1,"id":"starter","name":"Starter","price":5},{"n":2,"id":"premium","name":"Premium","price":10},{"n":3,"id":"pro","name":"Pro","price":20},{"n":4,"id":"ultimate","name":"Ultimate","price":50}],"categories":[{"id":"performance","name":"Performance","blurb":"Frame rate and CPU scheduling"},{"id":"stutter","name":"Stutter & 1% lows","blurb":"Frame pacing, shader cache and timers"},{"id":"gpu","name":"Graphics","blurb":"GPU scheduling and how frames reach the screen"},{"id":"overclock","name":"CPU & GPU","short":"CPU & GPU","blurb":"Boost, clocks and power states that keep the CPU and GPU at full speed"},{"id":"input","name":"Input","blurb":"Mouse, keyboard and controller response"},{"id":"mouse","name":"Mouse","blurb":"Pointer, aim, touchpad and pen response"},{"id":"keyboard","name":"Keyboard","blurb":"Typing response and shortcuts that interrupt games"},{"id":"network","name":"Network","blurb":"Latency, jitter and packet handling"},{"id":"power","name":"Power","blurb":"Clock speed and device power states"},{"id":"gamebar","name":"Game Bar & Xbox","blurb":"Recording, overlays and Xbox features"},{"id":"background","name":"Background apps","short":"Background","blurb":"Apps that keep running when you aren’t using them"},{"id":"services","name":"Services","blurb":"Windows services most gaming PCs don’t need"},{"id":"tasks","name":"Scheduled tasks","short":"Tasks","blurb":"Jobs Windows runs on a timer or at sign-in"},{"id":"privacy","name":"Privacy","blurb":"Telemetry, ads and data collection"},{"id":"updates","name":"Windows Update","blurb":"Restarts, drivers and update behavior"},{"id":"explorer","name":"Start, taskbar & Explorer","short":"Explorer","blurb":"Clutter, ads and everyday annoyances"},{"id":"visuals","name":"Visuals","blurb":"Desktop effects and UI speed"},{"id":"audio","name":"Audio & notifications","short":"Audio","blurb":"Sound behavior and pop-ups"},{"id":"storage","name":"Storage","blurb":"File system and disk cleanup behavior"}],"tweaks":[{"id":"ultimate-plan","cat":"performance","name":"Ultimate Performance power plan","desc":"Switches to a plan that keeps the CPU at full clocks and skips idle power-saving transitions. Uses more power.","tier":2,"impact":2},{"id":"game-mode","cat":"performance","name":"Game Mode","desc":"Lets Windows prioritize the game in focus and hold back update installs and notifications while you play.","tier":0,"impact":1},{"id":"mmcss-games","cat":"performance","name":"Prioritize games in the multimedia scheduler","desc":"Raises CPU and disk priority for games that register with the Windows multimedia scheduler (MMCSS).","tier":2,"impact":1},{"id":"sys-responsiveness","cat":"performance","name":"Reserve less CPU for background tasks","desc":"Lowers the share of CPU the multimedia scheduler holds back for background work from 20% to 10%.","tier":2,"impact":1},{"id":"power-throttling","cat":"performance","name":"Turn off power throttling","desc":"Stops Windows putting background apps — voice chat, overlays, recorders — into low-power mode while a game has focus.","tier":2,"impact":1},{"id":"paging-executive","cat":"performance","name":"Keep kernel code in RAM","desc":"Prevents Windows paging drivers and kernel code out to disk. Worthwhile with 16 GB of RAM or more.","tier":2,"impact":1},{"id":"mem-compression","cat":"performance","name":"Turn off memory compression","desc":"Skips compressing RAM pages to save CPU time. Only sensible with 32 GB of RAM or more.","tier":2,"impact":1},{"id":"sysmain","cat":"performance","name":"Turn off SysMain (Superfetch)","desc":"Stops app preloading. On an SSD the benefit is small, and turning it off removes background disk and CPU work. Also turns off memory compression.","tier":2,"impact":1},{"id":"search-index","cat":"performance","name":"Turn off search indexing","desc":"Stops background file indexing. Start menu file search gets slower and Outlook search may stop working.","tier":2,"impact":1},{"id":"compat-appraiser","cat":"performance","name":"Stop Compatibility Appraiser scans","desc":"Disables the CompatTelRunner tasks known for sudden CPU spikes that show up as stutter mid-game.","tier":2,"impact":1},{"id":"perftrack-off","cat":"performance","name":"Turn off PerfTrack responsiveness tracking","desc":"Stops Windows tracing slow app launches and hangs so it can send PerfTrack reports to Microsoft. Saves a little background tracing work and changes nothing you use.","tier":2,"impact":1},{"id":"wdi-boot-diag-off","cat":"performance","name":"Turn off boot performance diagnostics","desc":"Stops the Diagnostic Policy Service analysing each startup for slow drivers and apps. Windows boots the same way; it just stops logging the causes of slow boots.","tier":2,"impact":1},{"id":"wdi-shutdown-diag-off","cat":"performance","name":"Turn off shutdown performance diagnostics","desc":"Stops Windows analysing every shutdown for apps and services that slow it down. Shutdown works the same; the causes just aren’t logged any more.","tier":2,"impact":1},{"id":"wdi-resume-diag-off","cat":"performance","name":"Turn off sleep and resume diagnostics","desc":"Stops Windows analysing each sleep and wake-up for slow drivers. Sleep works the same; the causes of a slow resume just aren’t logged.","tier":2,"impact":1},{"id":"wdi-responsiveness-diag-off","cat":"performance","name":"Turn off system responsiveness diagnostics","desc":"Stops Windows watching for and analysing moments when the desktop or apps stop responding. A small cut in background tracing; nothing you use changes.","tier":2,"impact":1},{"id":"wdi-leak-diag-off","cat":"performance","name":"Turn off memory leak diagnosis","desc":"Stops Windows checking in the background for apps that keep eating memory and warning you about them. Only worth it if you never want those warnings.","tier":2,"impact":1},{"id":"api-sampling-off","cat":"performance","name":"Turn off API sampling","desc":"Stops Windows sampling which system functions your apps call to spot compatibility problems for Microsoft’s inventory. Less background monitoring; apps run the same.","tier":2,"impact":1},{"id":"index-battery-off","cat":"performance","name":"Pause search indexing on battery","desc":"On laptops, the search indexer waits until you plug in before indexing new files, so it doesn’t eat battery or disk time while you play unplugged. No effect on desktops.","tier":2,"impact":1},{"id":"folder-type-auto-off","cat":"performance","name":"Stop File Explorer guessing folder types","desc":"Explorer stops reading the files in each new folder to decide whether it holds pictures, music or videos, and opens it with the plain “General items” view. Big download and game folders open faster; folders Explorer has already remembered keep their view.","tier":2,"impact":1},{"id":"priority-separation","cat":"performance","name":"Boost the app you’re using","desc":"Gives the window in focus longer CPU time slices than background programs (3× the background length), so the game is interrupted less often by background work.","tier":2,"impact":1},{"id":"ndu-service","cat":"performance","name":"Turn off the network data-usage driver","desc":"Stops the Ndu driver that counts network use per app. Task Manager’s app-history network column and Settings’ data-usage page stop updating. Older Windows builds had a memory leak in this driver.","tier":2,"impact":1},{"id":"faster-shutdown","cat":"performance","name":"Shorter wait for services at shutdown","desc":"Lowers how long Windows waits on a stuck service before killing it at shutdown, from 5 seconds to 2.","tier":2,"impact":1},{"id":"shader-cache-keep","cat":"stutter","name":"Stop Windows deleting the shader cache","desc":"Disk Cleanup and automatic maintenance can wipe the DirectX shader cache, so every game rebuilds its shaders — and stutters — the next time you play. This keeps the cache.","tier":2,"impact":2},{"id":"vrr-windowed","cat":"stutter","name":"Variable refresh rate for windowed games","desc":"Lets G-SYNC and FreeSync work in borderless and windowed games that don’t support it themselves, smoothing out frame-rate dips. Only matters with a VRR monitor.","tier":2,"impact":1},{"id":"hags","cat":"gpu","name":"Hardware-accelerated GPU scheduling","desc":"Lets the GPU schedule its own work, which can cut latency and is required for DLSS Frame Generation. Results vary by game.","tier":0,"impact":1},{"id":"windowed-opt","cat":"gpu","name":"Optimizations for windowed games","desc":"Uses the modern flip presentation model for borderless and windowed DirectX 10/11 games, bringing latency close to exclusive fullscreen.","tier":0,"impact":2},{"id":"auto-hdr-off","cat":"gpu","name":"Turn off Auto HDR","desc":"Stops Windows converting SDR games to HDR. Turn it off if games look washed out or oversaturated on your HDR monitor.","tier":2,"impact":1},{"id":"oc-max-state","cat":"overclock","name":"Let the CPU reach full speed","desc":"Sets the maximum processor state to 100% on AC power for every core type. Some tools and laptop plans set it to 99%, which quietly turns off boost clocks.","tier":4,"impact":1},{"id":"oc-freq-cap-off","cat":"overclock","name":"Remove the CPU frequency cap","desc":"Sets “Maximum processor frequency” to 0 (no limit) on AC power for every core type, undoing a MHz cap left by a power plan or tuning tool. No cap is the Windows default.","tier":4,"impact":1},{"id":"oc-max-cores","cat":"overclock","name":"Let Windows use every core","desc":"Sets core parking’s “maximum cores” to 100% on AC power for every core type, so a power plan can’t cap how many cores a game is allowed to run on. This is the Windows default.","tier":4,"impact":1},{"id":"oc-class1-min-state","cat":"overclock","name":"Keep the second core type at full speed (hybrid CPUs)","desc":"On hybrid CPUs (Intel 12th gen and newer, some recent AMD chips) Windows keeps a separate minimum processor state for the second core type. This sets it to 100% on AC power too. Uses more power and runs warmer; does nothing on other CPUs.","tier":4,"impact":1},{"id":"oc-class1-parking","cat":"overclock","name":"Turn off core parking for the second core type (hybrid CPUs)","desc":"Keeps every core of the second core type on hybrid CPUs awake, matching what “Turn off core parking” does for the first. Avoids a wake-up delay when a game suddenly needs more threads; uses more power at idle.","tier":4,"impact":1},{"id":"oc-class1-epp","cat":"overclock","name":"Favor speed on the second core type (hybrid CPUs)","desc":"Sets the energy performance preference of the second core type on hybrid CPUs to maximum performance, matching “Favor speed over efficiency”. Uses more power and runs warmer.","tier":4,"impact":1},{"id":"oc-class1-inc-policy","cat":"overclock","name":"Ramp clocks up immediately on the second core type (hybrid CPUs)","desc":"Sets the performance increase policy of the second core type on hybrid CPUs to “Rocket”, jumping straight to high clocks when load arrives. Mostly matters where Windows, not the CPU, picks clock speeds.","tier":4,"impact":1},{"id":"oc-boost-policy","cat":"overclock","name":"Boost whenever possible","desc":"Raises the processor performance boost policy from 60% to 100%, so Windows asks for turbo clocks as readily as it can on CPUs where it manages boost itself. Uses more power and runs warmer.","tier":4,"impact":1},{"id":"oc-perf-thresholds","cat":"overclock","name":"Raise clocks at lower CPU load","desc":"Windows raises clocks once a core is 10% busy instead of 60%, and lowers them only when it drops below 5% instead of 20%. Only matters on CPUs where Windows picks clock speeds (no hardware-managed P-states); uses more power.","tier":4,"impact":1},{"id":"oc-inc-time","cat":"overclock","name":"Raise clocks after a single check","desc":"Sets the performance increase time to one check interval, so Windows raises clocks as soon as it sees load instead of waiting several checks. Only matters where Windows picks clock speeds.","tier":4,"impact":1},{"id":"oc-dec-time","cat":"overclock","name":"Hold clocks longer before dropping","desc":"Makes Windows wait five check intervals before lowering clocks, so short gaps between frames don’t drop the CPU to a low speed. Only matters where Windows picks clock speeds; uses a little more power.","tier":4,"impact":1},{"id":"oc-dec-policy","cat":"overclock","name":"Drop clocks one step at a time","desc":"Sets the performance decrease policy to “Single”, so when load falls the CPU steps down gradually instead of jumping straight to a low clock. Helps bursty game loads; only matters where Windows picks clock speeds.","tier":4,"impact":1},{"id":"oc-duty-cycling","cat":"overclock","name":"Turn off processor duty cycling","desc":"Stops Windows reaching very low performance levels by rapidly switching cores on and off (duty cycling) on CPUs that support it. Only changes the AC setting.","tier":4,"impact":1},{"id":"oc-latency-perf","cat":"overclock","name":"Full CPU speed on clicks and key presses","desc":"When Windows sees a latency-sensitive event — a mouse click, the Enter key, a touch — it briefly raises CPU performance to this level. Sets it to 100% (Windows uses 99%) for every core type.","tier":4,"impact":1},{"id":"oc-latency-unpark","cat":"overclock","name":"Unpark all cores on clicks and key presses","desc":"Sets the share of cores Windows wakes on a latency-sensitive event (click, Enter key, touch) to 100% for every core type, so work after a click never waits for a parked core.","tier":4,"impact":1},{"id":"oc-gpu-preference","cat":"overclock","name":"Don’t prefer the power-saving GPU when plugged in","desc":"Sets the power plan’s GPU preference policy to “No preference” on AC power, so Windows doesn’t steer apps to the low-power integrated GPU while plugged in. Most plans already do this.","tier":4,"impact":1},{"id":"oc-intel-gpu-plan","cat":"overclock","name":"Intel graphics at maximum performance","desc":"Sets the “Intel Graphics Power Plan” in your power plan to Maximum Performance on AC power, so Intel integrated graphics don’t hold clocks back to save power. Only on PCs whose Intel driver adds this setting; uses more power.","tier":4,"impact":1},{"id":"oc-show-cpu-options","cat":"overclock","name":"Show hidden CPU options in Power Options","desc":"Adds “Processor performance boost mode”, core parking minimum cores, energy performance preference and maximum processor frequency to the advanced Power Options page, so you can check and change them yourself.","tier":4,"impact":1},{"id":"oc-amd-ulps","cat":"overclock","name":"Turn off AMD Ultra Low Power State","desc":"Stops AMD Radeon cards dropping into ULPS deep sleep. Fixes slow wake-ups, stutter on multi-GPU setups and overclocking tools losing their settings; an idle second GPU then uses more power.","tier":4,"impact":1},{"id":"oc-hpet-unforce","cat":"overclock","name":"Don’t force the HPET timer","desc":"Makes sure Windows isn’t forced to use the slower HPET platform clock for timing — a leftover from old tweak guides that adds overhead to every timer read in games. Changes nothing if it was never forced.","tier":4,"impact":1},{"id":"mouse-accel","cat":"input","name":"Turn off mouse acceleration","desc":"Disables Enhance Pointer Precision so the cursor moves exactly as far as your hand does. The basis of consistent aim.","tier":0,"impact":2},{"id":"kbd-repeat","cat":"input","name":"Faster key repeat","desc":"Uses the shortest delay before a held key starts repeating, and the fastest repeat rate.","tier":2,"impact":1},{"id":"usb-suspend","cat":"input","name":"Turn off USB selective suspend","desc":"Keeps USB ports fully powered so your mouse, keyboard and headset never have to wake from a power-saving state.","tier":2,"impact":1},{"id":"sticky-keys","cat":"input","name":"Turn off the Sticky Keys shortcut","desc":"Stops the Sticky Keys prompt appearing when you tap Shift five times mid-game.","tier":0,"impact":1},{"id":"filter-keys","cat":"input","name":"Turn off the Filter Keys shortcut","desc":"Stops the Filter Keys prompt appearing when you hold right Shift for eight seconds.","tier":0,"impact":1},{"id":"toggle-keys","cat":"input","name":"Turn off the Toggle Keys shortcut","desc":"Stops the Toggle Keys prompt appearing when you hold Num Lock for five seconds.","tier":0,"impact":1},{"id":"mouse-keys","cat":"input","name":"Turn off the Mouse Keys shortcut","desc":"Stops Left Alt + Left Shift + Num Lock turning your number pad into a mouse.","tier":2,"impact":1},{"id":"high-contrast-key","cat":"input","name":"Turn off the High Contrast shortcut","desc":"Stops Left Alt + Left Shift + Print Screen switching Windows to high-contrast colors.","tier":2,"impact":1},{"id":"lang-hotkey","cat":"input","name":"Stop Alt + Shift switching keyboard language","desc":"Removes the shortcuts that switch input language or layout — a common cause of WASD suddenly typing the wrong letters mid-game.","tier":2,"impact":1},{"id":"narrator-key","cat":"input","name":"Turn off the Narrator shortcut","desc":"Stops Win + Ctrl + Enter starting Narrator by accident.","tier":2,"impact":1},{"id":"windows-ink","cat":"input","name":"Turn off Windows Ink Workspace","desc":"Removes the Windows Ink Workspace panel and its pen-button shortcut. Pen and drawing-tablet input is unchanged — that’s set in your tablet driver.","tier":2,"impact":1},{"id":"mouse-speed-1to1","cat":"mouse","name":"Set pointer speed to the 1:1 notch","desc":"Puts the Windows pointer-speed slider back on the middle notch (10 of 20). With “Enhance pointer precision” off, that is where one count from the mouse moves the cursor exactly one pixel; higher settings skip pixels and lower ones drop counts. Change your DPI in the mouse software instead.","tier":2,"impact":2},{"id":"mouse-trails-off","cat":"mouse","name":"Turn off pointer trails","desc":"Removes the ghost trail that follows the cursor, so the pointer is drawn once, where it actually is.","tier":2,"impact":1},{"id":"mouse-snap-off","cat":"mouse","name":"Stop the pointer jumping to dialog buttons","desc":"Turns off “Snap To”, which moves the cursor onto the default button whenever a dialog box opens, so the pointer stays where your hand put it.","tier":2,"impact":1},{"id":"mouse-doubleclick-fast","cat":"mouse","name":"Shorter double-click time","desc":"Two clicks must land within 400 ms instead of 500 ms to count as a double-click, so quick separate clicks are less often read as one double-click.","tier":2,"impact":1},{"id":"mouse-scroll-inactive-off","cat":"mouse","name":"Don’t scroll windows you’re only hovering over","desc":"The mouse wheel only scrolls the window you clicked into, not whatever window is under the pointer — so a chat or browser beside a windowed game won’t scroll by accident.","tier":2,"impact":1},{"id":"mouse-wheel-lines","cat":"mouse","name":"Scroll further per wheel notch","desc":"Each notch of the mouse wheel scrolls 5 lines (and 5 characters sideways) instead of 3. Games that read the wheel directly are unaffected.","tier":2,"impact":1},{"id":"mouse-drag-threshold","cat":"mouse","name":"Larger drag threshold","desc":"The pointer has to move 10 pixels instead of 4 with the button held before Windows starts a drag, so fast clicks on a high-DPI mouse don’t accidentally move files or icons.","tier":2,"impact":1},{"id":"caret-blink-off","cat":"mouse","name":"Stop the text cursor blinking","desc":"The blinking line where you type stays solid instead of flashing on and off.","tier":2,"impact":1},{"id":"touchpad-off-with-mouse","cat":"mouse","name":"Turn off the touchpad when a mouse is plugged in","desc":"Laptops only: the precision touchpad stops responding while a mouse is connected, so a wrist brushing it mid-game can’t move the cursor or click.","tier":2,"impact":1},{"id":"touchpad-palm-check","cat":"mouse","name":"Stronger touchpad palm rejection","desc":"Sets touchpad sensitivity to “Low sensitivity”, so taps and small movements right after you type are ignored for longer. Helps when your palm rests on the touchpad while using WASD.","tier":2,"impact":1},{"id":"touchpad-tap-off","cat":"mouse","name":"Turn off tap to click","desc":"A light tap on the touchpad no longer clicks; press it down to click instead. Stops accidental clicks from a resting finger or palm.","tier":2,"impact":1},{"id":"touchpad-two-finger-tap-off","cat":"mouse","name":"Turn off two-finger tap to right-click","desc":"Tapping the touchpad with two fingers no longer opens a right-click menu.","tier":2,"impact":1},{"id":"touchpad-corner-click-off","cat":"mouse","name":"Turn off right-click in the touchpad corner","desc":"Pressing the lower-right corner of the touchpad clicks normally instead of right-clicking.","tier":2,"impact":1},{"id":"touchpad-tap-drag-off","cat":"mouse","name":"Turn off tap twice and drag","desc":"A double tap followed by a slide no longer drags or multi-selects, so quick taps can’t accidentally pick up and move things.","tier":2,"impact":1},{"id":"touchpad-pinch-zoom-off","cat":"mouse","name":"Turn off touchpad pinch to zoom","desc":"Moving two fingers apart or together on the touchpad no longer zooms, so stray two-finger contact can’t resize a page or a game window.","tier":2,"impact":1},{"id":"touchpad-scroll-like-wheel","cat":"mouse","name":"Touchpad scrolls like a mouse wheel","desc":"Sets the touchpad scrolling direction to “Down motion scrolls down”, matching a mouse wheel, instead of the default where content follows your fingers.","tier":2,"impact":1},{"id":"touchpad-3f-swipe-off","cat":"mouse","name":"Turn off three-finger touchpad swipes","desc":"Three-finger swipes no longer switch apps or show the desktop, so a clumsy swipe can’t minimize your game.","tier":2,"impact":1},{"id":"touchpad-3f-tap-middle","cat":"mouse","name":"Three-finger tap = middle click","desc":"A three-finger tap on the touchpad becomes a middle mouse button instead of opening Search — handy for opening links in new tabs or games that bind the middle button.","tier":2,"impact":1},{"id":"touchpad-4f-swipe-off","cat":"mouse","name":"Turn off four-finger touchpad swipes","desc":"Four-finger swipes no longer switch virtual desktops or show the desktop, so a palm sliding over the touchpad can’t throw you out of a game.","tier":2,"impact":1},{"id":"touchpad-4f-tap-off","cat":"mouse","name":"Turn off the four-finger touchpad tap","desc":"A four-finger tap on the touchpad does nothing instead of opening a Windows panel over your game.","tier":2,"impact":1},{"id":"touch-gestures-system-off","cat":"mouse","name":"Turn off three- and four-finger touchscreen gestures","desc":"Windows stops using three- and four-finger touches on the screen to switch or minimize windows, and passes them to the app instead — so touch games and drawing apps get every finger.","tier":2,"impact":1},{"id":"touch-edge-swipe-off","cat":"mouse","name":"Turn off touchscreen edge swipes","desc":"Swiping in from the edge of a touchscreen no longer opens Task View, widgets or notifications, so it can’t interrupt a game you’re playing with touch.","tier":2,"impact":1},{"id":"touch-feedback-off","cat":"mouse","name":"Turn off touch visual feedback","desc":"Removes the circles and gesture trails Windows draws under your fingers on a touchscreen.","tier":2,"impact":1},{"id":"pen-effects-off","cat":"mouse","name":"Turn off pen visual effects","desc":"Stops the ripple Windows draws where the pen touches the screen. The pen cursor itself still shows.","tier":2,"impact":1},{"id":"touchscreen-off","cat":"mouse","name":"Turn off touchscreen input","desc":"Uses the “Turn off Tablet PC touch input” policy so the touchscreen ignores fingers. For laptops whose screen registers stray or ghost touches during games.","tier":2,"impact":1},{"id":"kb-color-filter-key","cat":"keyboard","name":"Turn off the color filter shortcut","desc":"Stops Win + Ctrl + C switching the screen to grayscale or another color filter if you hit it by accident. Color filters still work from Settings.","tier":2,"impact":1},{"id":"kb-printscreen-snip","cat":"keyboard","name":"Print Screen copies the screen instead of opening Snipping Tool","desc":"Print Screen goes back to copying the whole screen to the clipboard, instead of opening the Snipping Tool overlay on top of your game. Win + Shift + S still opens Snipping Tool.","tier":2,"impact":1},{"id":"kb-no-win-hotkeys","cat":"keyboard","name":"Turn off Windows key shortcuts","desc":"Turns off the Win + letter shortcuts (Win + D, Win + E, Win + R and the rest), so a stray Windows key combo can’t throw you out of a game. The Windows key on its own still opens Start.","tier":2,"impact":1},{"id":"kb-hw-suggestions","cat":"keyboard","name":"Turn off text suggestions for the physical keyboard","desc":"Stops Windows showing word suggestions above the text box while you type on your keyboard.","tier":2,"impact":1},{"id":"kb-multilingual","cat":"keyboard","name":"Turn off multilingual text suggestions","desc":"Text suggestions use only your current keyboard language instead of guessing from every language you have installed.","tier":2,"impact":1},{"id":"kb-autocorrect","cat":"keyboard","name":"Turn off autocorrect","desc":"Stops Windows changing words it thinks are misspelled as you type, so names, slang and game terms stay exactly as typed.","tier":2,"impact":1},{"id":"kb-spell-highlight","cat":"keyboard","name":"Don’t underline misspelled words","desc":"Removes the red squiggly underline that Windows draws under words it doesn’t recognize.","tier":2,"impact":1},{"id":"kb-touch-suggestions","cat":"keyboard","name":"Turn off touch keyboard text suggestions","desc":"Hides the word suggestions shown above the on-screen touch keyboard.","tier":2,"impact":1},{"id":"kb-touch-autoshow","cat":"keyboard","name":"Don’t pop up the touch keyboard automatically","desc":"Stops the on-screen keyboard sliding up when you tap a text box with no keyboard attached — handy on handheld gaming PCs. You can still open it yourself.","tier":2,"impact":1},{"id":"kb-touch-icon","cat":"keyboard","name":"Hide the touch keyboard button on the taskbar","desc":"Removes the keyboard icon from the taskbar corner.","tier":2,"impact":1},{"id":"kb-touch-sounds","cat":"keyboard","name":"Turn off touch keyboard key sounds","desc":"Stops the click sound each time you tap a key on the on-screen touch keyboard.","tier":2,"impact":1},{"id":"kb-touch-autocap","cat":"keyboard","name":"Don’t capitalize the first letter on the touch keyboard","desc":"Stops the touch keyboard switching to a capital letter at the start of each sentence.","tier":2,"impact":1},{"id":"kb-touch-shiftlock","cat":"keyboard","name":"Turn off double-tap Shift for caps on the touch keyboard","desc":"Double-tapping Shift on the touch keyboard no longer locks it into all capitals.","tier":2,"impact":1},{"id":"kb-touch-double-space","cat":"keyboard","name":"Don’t add a period after a double space on the touch keyboard","desc":"Double-tapping the space bar on the touch keyboard types two spaces instead of a period and a space.","tier":2,"impact":1},{"id":"kb-improve-typing","cat":"keyboard","name":"Don’t send typing data to improve recognition","desc":"Turns off “Improve inking and typing”, so samples of what you type and write aren’t sent to Microsoft.","tier":2,"impact":1},{"id":"kb-learning-policy","cat":"keyboard","name":"Turn off automatic typing and handwriting learning","desc":"Sets the “Turn off automatic learning” policy, so Windows stops building a personal word list from your typing and handwriting on every account.","tier":2,"impact":1},{"id":"kb-suggested-actions","cat":"keyboard","name":"Turn off suggested actions when copying","desc":"Stops the small pop-up that offers to call a number or add an event when you copy a phone number or date.","tier":2,"impact":1},{"id":"kb-shift-capslock","cat":"keyboard","name":"Press Shift to turn off Caps Lock","desc":"Pressing Shift turns Caps Lock off, so a Caps Lock bumped mid-game is undone by the next Shift. Caps Lock itself then only turns it on.","tier":2,"impact":1},{"id":"kb-underline-keys","cat":"keyboard","name":"Always underline access keys","desc":"Underlines the Alt shortcut letter in menus and buttons all the time, not only after you press Alt.","tier":2,"impact":1},{"id":"kb-caret-wide","cat":"keyboard","name":"Thicker text cursor","desc":"Draws the text cursor 3 pixels wide instead of 1, so it’s easier to spot on high-resolution screens.","tier":2,"impact":1},{"id":"kb-inline-autocomplete","cat":"keyboard","name":"Inline autocomplete in Run and File Explorer","desc":"Fills in the rest of a path or command as you type in the Run box, the File Explorer address bar and Open/Save dialogs; press Enter to accept it.","tier":2,"impact":1},{"id":"kb-no-autosuggest","cat":"keyboard","name":"Turn off the suggestion list in Run and File Explorer","desc":"Stops the drop-down of past entries appearing under the Run box and the File Explorer address bar as you type.","tier":2,"impact":1},{"id":"kb-explorer-typeahead","cat":"keyboard","name":"Typing in a folder searches it","desc":"When you start typing in a File Explorer folder, the text goes into the search box instead of jumping to the file whose name starts with those letters.","tier":2,"impact":1},{"id":"tcp-ack","cat":"network","name":"Turn off delayed TCP acknowledgements","desc":"Acknowledges every TCP packet right away instead of waiting up to 200 ms. Can help TCP-based games such as MMOs; most shooters use UDP and won’t change.","tier":3,"impact":1},{"id":"tcp-nodelay","cat":"network","name":"Turn off Nagle’s algorithm","desc":"Sends small TCP packets immediately instead of bundling them. Pairs with the delayed-acknowledgement tweak for TCP games; UDP games are unaffected.","tier":3,"impact":1},{"id":"net-throttling","cat":"network","name":"Turn off network throttling","desc":"Stops Windows rate-limiting network traffic while audio or video plays — music or Discord running during a match.","tier":3,"impact":1},{"id":"nic-intmod","cat":"network","name":"Turn off interrupt moderation","desc":"Makes the network adapter hand packets to the CPU immediately instead of batching them. Lower latency, slightly more CPU use.","tier":3,"impact":1},{"id":"nic-eee","cat":"network","name":"Turn off Energy-Efficient Ethernet","desc":"Stops the Ethernet link dropping into a low-power state between packets, which can add jitter.","tier":3,"impact":1},{"id":"nic-green","cat":"network","name":"Turn off Green Ethernet (Realtek)","desc":"Realtek’s own power saving that lowers signal power on short cables. Only appears on Realtek adapters.","tier":3,"impact":1},{"id":"nic-gigalite","cat":"network","name":"Turn off GigaLite (Realtek)","desc":"Stops Realtek adapters dropping to a slower power-saving link mode.","tier":3,"impact":1},{"id":"nic-powersave","cat":"network","name":"Turn off adapter power saving mode (Realtek)","desc":"Keeps Realtek adapters out of their own idle power-saving state between bursts of traffic.","tier":3,"impact":1},{"id":"nic-adv-eee","cat":"network","name":"Turn off Advanced EEE (Realtek)","desc":"Realtek’s extended version of Energy-Efficient Ethernet. Adds wake-up delay between packets.","tier":3,"impact":1},{"id":"nic-reduce-speed","cat":"network","name":"Don’t slow the link when idle (Intel)","desc":"Stops Intel adapters reducing link speed to save power.","tier":3,"impact":1},{"id":"nic-ulp","cat":"network","name":"Turn off Ultra Low Power mode (Intel)","desc":"Stops Intel adapters dropping into their lowest power state when the link is quiet.","tier":3,"impact":1},{"id":"nic-wol","cat":"network","name":"Turn off Wake on LAN","desc":"Stops network traffic waking your PC from sleep. Leave it on if you wake the PC remotely.","tier":3,"impact":1},{"id":"nic-power","cat":"network","name":"Stop Windows turning off the network adapter","desc":"Prevents Windows powering down your network adapter to save energy.","tier":3,"impact":1},{"id":"rss","cat":"network","name":"Receive-side scaling on","desc":"Spreads network processing across CPU cores. On by default — this turns it back on if another tool switched it off.","tier":3,"impact":1},{"id":"autotuning","cat":"network","name":"TCP auto-tuning on normal","desc":"Keeps TCP receive windows sized automatically. Some tweak tools disable this, which slows downloads.","tier":3,"impact":1},{"id":"delivery-opt","cat":"network","name":"Stop sharing updates with other PCs","desc":"Turns off Delivery Optimization peer sharing, so Windows doesn’t upload updates to other PCs on your network — or the internet, if that was allowed — while you play.","tier":3,"impact":1},{"id":"dns-neg-cache","cat":"network","name":"Don’t remember failed DNS lookups","desc":"Stops Windows caching a failed lookup for up to 15 minutes, so a brief DNS hiccup doesn’t keep a game or launcher from reaching its servers.","tier":3,"impact":1},{"id":"llmnr-off","cat":"network","name":"Turn off LLMNR name broadcasts","desc":"Stops Windows shouting name lookups to every device on the network when DNS fails. Fewer broadcasts and a common security recommendation.","tier":3,"impact":1},{"id":"nic-checksum-on","cat":"network","name":"Checksum offload on","desc":"Lets the network adapter check and fill in IP, TCP and UDP checksums instead of the CPU. On by default — this turns it back on if another tool switched it off.","tier":3,"impact":1},{"id":"nic-jumbo-off","cat":"network","name":"Standard Ethernet frame size","desc":"Turns jumbo frames back off. They only help when every device on the network supports them; on a normal home network they can cause dropped or fragmented packets.","tier":3,"impact":1},{"id":"nic-selective-suspend","cat":"network","name":"Turn off adapter selective suspend","desc":"Stops USB network adapters and Wi-Fi dongles suspending themselves when idle, which can add a wake-up delay or a brief disconnect. Built-in adapters usually don’t have this setting.","tier":3,"impact":1},{"id":"nic-idle-restrict","cat":"network","name":"Keep the adapter awake while you use the PC","desc":"On newer network drivers, stops the adapter powering down while you’re at the PC; it can still idle when you’re away. Most adapters don’t offer this setting yet.","tier":3,"impact":1},{"id":"nic-packet-coalescing","cat":"network","name":"Turn off packet coalescing","desc":"Stops the adapter holding back broadcast and multicast packets to save power, so they’re handled as they arrive. Normal game traffic isn’t coalesced, so the effect is small; uses slightly more power.","tier":3,"impact":1},{"id":"nic-wake-pattern","cat":"network","name":"Don’t wake from sleep on network traffic","desc":"Stops ordinary network packets that match a wake pattern from waking the PC — a common cause of a PC waking up on its own. Wake on LAN magic packets are a separate setting.","tier":3,"impact":1},{"id":"nic-standby-wol","cat":"network","name":"Turn off Wake on LAN during Modern Standby","desc":"Stops magic packets waking laptops and other Modern Standby PCs from standby, which can drain the battery. Off by default on most adapters; some manufacturers turn it on.","tier":3,"impact":1},{"id":"nic-roam-lowest","cat":"network","name":"Lowest Wi-Fi roaming aggressiveness (Intel)","desc":"Makes Intel Wi-Fi adapters stay on the current access point instead of scanning for a better one, which can cause ping spikes. Best for a PC that doesn’t move; a laptop carried between rooms may hold on to a weak signal longer.","tier":3,"impact":1},{"id":"nic-prefer-5ghz","cat":"network","name":"Prefer 5 GHz Wi-Fi (Intel)","desc":"Makes Intel Wi-Fi adapters pick the 5 GHz band when your router offers both. 5 GHz is usually faster and less crowded but has shorter range through walls.","tier":3,"impact":1},{"id":"tcp-task-offload-on","cat":"network","name":"TCP/IP offloads on","desc":"Makes sure Windows lets the network adapter take checksum and segmentation work off the CPU. On by default — this undoes tools that switch every offload off, which only adds CPU load.","tier":3,"impact":1},{"id":"tcp-keepalive","cat":"network","name":"Check idle connections every 5 minutes","desc":"Sends keep-alive checks on idle TCP connections that ask for them every 5 minutes instead of every 2 hours, so dead connections are noticed sooner. A common security baseline setting.","tier":3,"impact":1},{"id":"icmp-redirect-off","cat":"network","name":"Ignore ICMP redirects","desc":"Stops ICMP redirect messages from changing Windows’ routing table. A standard security baseline setting; it doesn’t change speed on a home network.","tier":3,"impact":1},{"id":"source-routing-off","cat":"network","name":"Drop source-routed packets","desc":"Discards IPv4 and IPv6 packets that try to choose their own route through your PC. A standard security baseline setting with no effect on normal traffic.","tier":3,"impact":1},{"id":"netbt-name-release","cat":"network","name":"Ignore NetBIOS name-release requests","desc":"Stops other devices on the network forcing your PC to give up its NetBIOS name. A standard security baseline setting; nothing you use changes.","tier":3,"impact":1},{"id":"smb-throttle-off","cat":"network","name":"Turn off file-sharing bandwidth throttling","desc":"Lets the Windows file-sharing client keep more data in flight on slow or high-latency links instead of throttling itself. Helps copies to a NAS or another PC; games aren’t affected.","tier":3,"impact":1},{"id":"dns-smart-multihomed-off","cat":"network","name":"Ask DNS one adapter at a time","desc":"Stops Windows racing DNS, LLMNR and NetBIOS lookups in parallel across all adapters; DNS is tried first, then LLMNR, then NetBIOS. Mainly for VPN and multi-network setups — on its own it doesn’t guarantee lookups stay inside a VPN.","tier":3,"impact":1},{"id":"mdns-off","cat":"network","name":"Turn off multicast DNS (mDNS)","desc":"Stops Windows announcing and looking up names with multicast DNS on the local network. Fewer broadcasts, but Windows can no longer find devices that rely on it.","tier":3,"impact":1},{"id":"netbios-public-off","cat":"network","name":"No NetBIOS name lookups on public networks","desc":"Stops Windows falling back to NetBIOS broadcasts to find names on networks marked Public, such as café or hotel Wi-Fi. Your home network keeps working as before.","tier":3,"impact":1},{"id":"dns-registration-off","cat":"network","name":"Don’t register this PC’s name in DNS","desc":"Stops Windows asking the network’s DNS server to record this PC’s name and address. Home routers ignore these requests; work networks may rely on them.","tier":3,"impact":1},{"id":"wpad-off","cat":"network","name":"Turn off automatic proxy discovery (WPAD)","desc":"Stops Windows services looking for a “wpad” proxy configuration on the network, which home networks never have and attackers can fake. Proxies then have to be set by hand.","tier":3,"impact":1},{"id":"teredo-off","cat":"network","name":"Turn off Teredo","desc":"Removes the Teredo IPv6 tunnel. Xbox networking on PC uses it for party chat and some multiplayer connections, so only turn it off if you don’t use those.","tier":3,"impact":1},{"id":"ipv6-old-tunnels-off","cat":"network","name":"Turn off old IPv6 tunnels (6to4, ISATAP)","desc":"Keeps the outdated 6to4 and ISATAP tunnel adapters switched off. Recent Windows versions already leave them unused; your normal IPv4 and IPv6 connection is unaffected.","tier":3,"impact":1},{"id":"lltd-protocols-off","cat":"network","name":"Turn off the network map protocols","desc":"Turns off the Link-Layer Topology Discovery mapper and responder drivers that probe and answer for the network map. Pairs with the network map service tweak.","tier":3,"impact":1},{"id":"net-discovery-svcs","cat":"network","name":"Turn off network discovery services","desc":"Stops Function Discovery searching for other PCs and devices and announcing this PC to them. The Network folder in File Explorer stays empty.","tier":3,"impact":1},{"id":"upnp-svcs","cat":"network","name":"Turn off UPnP discovery","desc":"Stops the SSDP Discovery and UPnP Device Host services that find smart TVs, media servers and other UPnP devices. Apps that open router ports through Windows’ UPnP support may get a stricter NAT.","tier":3,"impact":1},{"id":"wifi-off-on-ethernet","cat":"network","name":"No Wi-Fi while Ethernet is connected","desc":"Blocks Wi-Fi connections, automatic and manual, while an Ethernet cable is connected, so traffic never drifts onto the slower link. Wi-Fi comes back when you unplug.","tier":3,"impact":1},{"id":"projection-to-pc-off","cat":"network","name":"Don’t let other devices project to this PC","desc":"Stops this PC offering itself as a wireless display for phones and other PCs. Casting from this PC to a TV still works.","tier":3,"impact":1},{"id":"qos-reserve","cat":"network","name":"Free reserved QoS bandwidth","desc":"Sets the QoS Packet Scheduler’s reservable-bandwidth limit to 0%. Windows doesn’t hold bandwidth back unless an app reserves it, so most PCs see no difference.","tier":3,"impact":1},{"id":"tcp-timewait-short","cat":"network","name":"Release closed connections sooner","desc":"Shortens how long closed TCP connections are held in TIME_WAIT from 2 minutes to 30 seconds, so their ports can be reused sooner.","tier":3,"impact":1},{"id":"cpu-min-state","cat":"power","name":"Keep the CPU at full speed","desc":"Sets the minimum processor state to 100% on AC power so clocks don’t drop between frames.","tier":3,"impact":1},{"id":"core-parking","cat":"power","name":"Turn off core parking","desc":"Keeps every CPU core awake instead of parking idle ones, avoiding wake-up delay when a game suddenly needs more threads.","tier":3,"impact":1},{"id":"boost-mode","cat":"power","name":"Aggressive CPU boost","desc":"Tells the CPU to boost to its highest clocks as soon as there is load.","tier":3,"impact":1},{"id":"cpu-epp","cat":"power","name":"Favor speed over efficiency","desc":"Sets the CPU energy performance preference to maximum performance on modern Intel and AMD processors.","tier":3,"impact":1},{"id":"perf-inc-policy","cat":"power","name":"Ramp clocks up immediately","desc":"Sets the processor performance increase policy to “Rocket”, jumping straight to high clocks when load arrives. Most useful on CPUs without hardware-managed boost.","tier":3,"impact":1},{"id":"hybrid-pcores","cat":"power","name":"Prefer performance cores (Intel 12th gen and newer)","desc":"Tells the Windows scheduler to prefer P-cores over E-cores for both long and short-running threads, so game threads don’t land on the slower cores.","tier":3,"impact":1},{"id":"throttle-states","cat":"power","name":"Turn off processor throttle states","desc":"Disables legacy clock-modulation (T-states) so the CPU never throttles this way under load. Most modern CPUs rarely use them.","tier":3,"impact":1},{"id":"pcie-aspm","cat":"power","name":"Turn off PCIe link power saving","desc":"Keeps PCIe links to your graphics and network cards out of power-saving states. Only takes effect where the firmware lets Windows control link power.","tier":3,"impact":1},{"id":"usb3-lpm","cat":"power","name":"Turn off USB 3 link power management","desc":"Keeps USB 3 links fully active so fast devices — capture cards, headsets, wireless dongles — don’t pause to wake up.","tier":3,"impact":1},{"id":"ahci-lpm","cat":"power","name":"Turn off SATA link power saving","desc":"Keeps SATA SSD and hard-drive links active, avoiding a short stall when a game streams data after a quiet moment.","tier":3,"impact":1},{"id":"disk-idle","cat":"power","name":"Never spin down drives","desc":"Stops hard drives powering down, which causes a stall when a game next loads from them.","tier":3,"impact":1},{"id":"wifi-power","cat":"power","name":"Wi-Fi adapter at maximum performance","desc":"Keeps the Wi-Fi adapter out of power-saving on battery as well as AC. Windows normally power-saves only on battery, so this matters most on laptops.","tier":3,"impact":1},{"id":"wake-timers","cat":"power","name":"Turn off wake timers","desc":"Stops scheduled jobs — mostly updates and maintenance — waking your PC in the middle of the night.","tier":3,"impact":1},{"id":"sleep-ac-never","cat":"power","name":"Never sleep while plugged in","desc":"Stops the PC sleeping on AC power, so long downloads and game updates finish overnight.","tier":3,"impact":1},{"id":"hibernation","cat":"power","name":"Turn off hibernation","desc":"Deletes the hibernation file (often 10 GB or more) from your system drive. Also turns off Fast Startup and hybrid sleep, so a power cut while asleep loses unsaved work.","tier":3,"impact":1},{"id":"fast-startup","cat":"power","name":"Turn off Fast Startup","desc":"Makes Shut down a full shutdown so drivers start clean instead of carrying state between boots.","tier":3,"impact":1},{"id":"game-dvr","cat":"gamebar","name":"Turn off Game Bar capture","desc":"Turns off Xbox Game Bar clips, screenshots and background recording, so its capture hooks don’t load into games. Your GPU’s own recorder and OBS still work.","tier":2,"impact":1},{"id":"gamedvr-policy","cat":"gamebar","name":"Block Game Bar recording completely","desc":"Turns off Game Bar’s recording and broadcasting with a policy, so updates can’t turn it back on. Use your GPU’s recorder or OBS instead.","tier":2,"impact":1},{"id":"gamedvr-service","cat":"gamebar","name":"Turn off the Game DVR service","desc":"Disables the background service behind Game Bar captures and broadcasts.","tier":2,"impact":1},{"id":"gamebar-tips","cat":"gamebar","name":"Turn off Game Bar tips","desc":"Stops the “Press Win + G” pop-up when games launch.","tier":0,"impact":1},{"id":"gamebar-button","cat":"gamebar","name":"Stop the controller button opening Game Bar","desc":"Pressing the Xbox button on your controller won’t throw Game Bar over your game.","tier":2,"impact":1},{"id":"xbox-services","cat":"gamebar","name":"Turn off Xbox services","desc":"Disables Xbox Live sign-in, cloud saves, networking and accessory services. Breaks the Xbox app, Game Pass PC games and Xbox controller updates — only for PCs that never use them.","tier":2,"impact":1},{"id":"task-xbl-save","cat":"gamebar","name":"Stop the Xbox cloud-save task","desc":"Disables the scheduled task that syncs Xbox game saves. Leave it on if you play Game Pass or Microsoft Store games.","tier":2,"impact":1},{"id":"background-apps","cat":"background","name":"Stop Store apps running in the background","desc":"Blocks Microsoft Store apps from running when you aren’t using them. Some won’t notify you until opened.","tier":2,"impact":1},{"id":"startup-delay","cat":"background","name":"Remove startup app delay","desc":"Starts your startup apps right after sign-in instead of waiting through Windows’ built-in delay.","tier":2,"impact":1},{"id":"edge-boost","cat":"background","name":"Stop Microsoft Edge running in the background","desc":"Turns off Edge Startup Boost and background mode so Edge isn’t holding RAM while you play. Edge will say it’s “managed by your organization”.","tier":2,"impact":1},{"id":"chrome-bg","cat":"background","name":"Stop Google Chrome running after you close it","desc":"Turns off Chrome’s “continue running background apps” setting. Chrome will say it’s managed by your organization.","tier":2,"impact":1},{"id":"edge-shopping-off","cat":"background","name":"Turn off Edge shopping and recommendations","desc":"Removes the Edge shopping assistant pop-ups and promotional recommendations.","tier":2,"impact":1},{"id":"edge-sidebar","cat":"background","name":"Turn off the Edge sidebar","desc":"Removes the Edge sidebar, including Copilot in Edge and sidebar apps.","tier":2,"impact":1},{"id":"widgets","cat":"background","name":"Turn off Widgets","desc":"Removes the Widgets board and the background web processes that feed it.","tier":2,"impact":1},{"id":"news-interests","cat":"background","name":"Turn off News and Interests","desc":"Removes the taskbar news and weather feed and its background process.","tier":2,"impact":1},{"id":"copilot-off","cat":"background","name":"Turn off the Windows Copilot sidebar","desc":"Turns off the built-in Copilot sidebar on builds that have it. The newer Copilot app is a normal app you can uninstall.","tier":2,"impact":1},{"id":"store-updates","cat":"background","name":"Pause automatic Store app updates","desc":"Stops Microsoft Store apps updating in the background. Update them yourself from the Store — some security fixes (codecs, App Installer) only arrive this way.","tier":2,"impact":1},{"id":"onedrive-startup","cat":"background","name":"Stop OneDrive starting with Windows","desc":"Removes OneDrive from startup. Files stop syncing until you open OneDrive.","tier":2,"impact":1},{"id":"recall","cat":"background","name":"Turn off Recall snapshots","desc":"Stops Windows Recall saving screen snapshots every few seconds on Copilot+ PCs.","tier":2,"impact":1},{"id":"widgets-lockscreen","cat":"background","name":"Turn off widgets on the lock screen","desc":"Removes weather, stocks and other widgets from the lock screen, so they don’t load in the background.","tier":2,"impact":1},{"id":"click-to-do-off","cat":"background","name":"Turn off Click to Do","desc":"Removes Click to Do, the on-screen AI actions on Copilot+ PCs. No effect on other PCs.","tier":2,"impact":1},{"id":"onedrive-pre-signin","cat":"background","name":"Keep OneDrive offline until you sign in","desc":"Stops OneDrive connecting to the network before anyone has signed in to Windows.","tier":2,"impact":1},{"id":"onedrive-kfm-block","cat":"background","name":"Keep Desktop and Documents out of OneDrive","desc":"Stops OneDrive offering to move your Desktop, Documents and Pictures folders into OneDrive. Keeps game saves and configs in Documents local.","tier":2,"impact":1},{"id":"edge-first-run","cat":"background","name":"Skip Edge’s first-run setup","desc":"Edge opens straight to a page instead of its sign-in and data import setup screens.","tier":2,"impact":1},{"id":"edge-ntp-prerender","cat":"background","name":"Stop Edge preloading the new tab page","desc":"Edge no longer builds a hidden new tab page in the background. New tabs may take a moment longer to appear.","tier":2,"impact":1},{"id":"edge-drop","cat":"background","name":"Turn off Drop in Edge","desc":"Removes Edge’s Drop panel for sending files and notes between your devices through OneDrive.","tier":2,"impact":1},{"id":"firefox-browser-agent","cat":"background","name":"Turn off the Firefox default browser agent","desc":"Stops Firefox’s scheduled background agent, which reports which browser is your default to Mozilla.","tier":2,"impact":1},{"id":"edge-collections","cat":"background","name":"Turn off Edge Collections","desc":"Removes the Collections button and feature from Microsoft Edge.","tier":2,"impact":1},{"id":"edge-follow","cat":"background","name":"Turn off Edge “Follow creators”","desc":"Disables the Follow-creators feature in Edge.","tier":2,"impact":1},{"id":"edge-promos","cat":"background","name":"Turn off Edge promotions","desc":"Stops Edge’s promotional tabs and the spotlight recommendations on the new-tab page.","tier":2,"impact":1},{"id":"edge-rewards","cat":"background","name":"Turn off Microsoft Rewards in Edge","desc":"Removes the Microsoft Rewards button from Edge.","tier":2,"impact":1},{"id":"edge-bar","cat":"background","name":"Turn off the Edge bar/widget","desc":"Blocks the standalone Edge web widget and bar.","tier":2,"impact":1},{"id":"edge-newtab","cat":"background","name":"Clean up the Edge new-tab page","desc":"Turns off the content feed on Edge’s new-tab page and hides the default top sites.","tier":2,"impact":1},{"id":"edge-feedback","cat":"background","name":"Turn off Edge feedback","desc":"Removes the “Send feedback” (smiley) button from Edge.","tier":2,"impact":1},{"id":"edge-default-nag","cat":"background","name":"Stop Edge’s “make me default” nags","desc":"Stops Edge prompting you to set it as the default browser.","tier":2,"impact":1},{"id":"svc-ncd-autosetup","cat":"services","name":"Turn off network device auto-setup","desc":"Stops Windows automatically finding and installing printers, TVs and other devices it sees on your network.","tier":2,"impact":1},{"id":"svc-print-workflow","cat":"services","name":"Turn off print workflow","desc":"Stops the per-user service that runs printer apps and print workflows. Only worth it if you never print.","tier":2,"impact":1},{"id":"svc-agent-activation","cat":"services","name":"Turn off Agent Activation Runtime","desc":"Stops the service that lets voice assistants such as Cortana or Alexa wake up and listen.","tier":2,"impact":1},{"id":"svc-alg","cat":"services","name":"Turn off Application Layer Gateway","desc":"Stops the helper that lets Internet Connection Sharing handle protocols like FTP. Not used unless this PC shares its connection.","tier":2,"impact":1},{"id":"svc-rasauto","cat":"services","name":"Turn off Remote Access Auto Connection Manager","desc":"Stops Windows automatically dialling a dial-up or VPN connection when a program asks for a remote address.","tier":2,"impact":1},{"id":"svc-block-backup","cat":"services","name":"Turn off the Block Level Backup Engine","desc":"Stops the engine behind “Backup and Restore (Windows 7)” system images and wbadmin. File History and OneDrive aren’t affected.","tier":2,"impact":1},{"id":"svc-storage-tiers","cat":"services","name":"Turn off Storage Tiers Management","desc":"Stops the service and task that move data between fast and slow drives in a tiered Storage Space. Normal drives don’t use it.","tier":2,"impact":1},{"id":"svc-nv-container","cat":"services","name":"Turn off NVIDIA LocalSystem Container","desc":"Stops the NVIDIA app / GeForce Experience background service. The overlay, Instant Replay, game filters and automatic driver checks stop; the driver and NVIDIA Control Panel keep working.","tier":2,"impact":1},{"id":"svc-intel-esrv","cat":"services","name":"Turn off Intel Energy Server telemetry","desc":"Stops Intel’s Energy Server service (part of the Intel Computing Improvement Program and System Usage Report), which collects usage data in the background.","tier":2,"impact":1},{"id":"spooler","cat":"services","name":"Turn off the print spooler","desc":"Stops the printing service. Only turn this off if you never print.","tier":2,"impact":1},{"id":"print-notify","cat":"services","name":"Turn off printer extensions and notifications","desc":"Stops the service that shows printer pop-ups and runs printer apps.","tier":2,"impact":1},{"id":"fax","cat":"services","name":"Turn off Fax","desc":"Stops the fax service.","tier":2,"impact":1},{"id":"maps-broker","cat":"services","name":"Start the Maps service only when needed","desc":"Stops Downloaded Maps Manager starting at boot. It still starts when you open Maps.","tier":2,"impact":1},{"id":"pcasvc","cat":"services","name":"Turn off Program Compatibility Assistant","desc":"Stops the service that watches programs for compatibility problems and shows prompts.","tier":2,"impact":1},{"id":"trkwks","cat":"services","name":"Turn off link tracking","desc":"Stops the Distributed Link Tracking Client, which follows shortcuts across network drives. Home PCs rarely need it.","tier":2,"impact":1},{"id":"cdpsvc","cat":"services","name":"Turn off Connected Devices Platform","desc":"Stops the service behind Phone Link and Nearby Sharing. Leave it on if you use them.","tier":2,"impact":1},{"id":"cdp-user","cat":"services","name":"Turn off the Connected Devices user service","desc":"The per-user half of Connected Devices Platform, used by Phone Link and timeline sync.","tier":2,"impact":1},{"id":"retail-demo","cat":"services","name":"Turn off Retail Demo","desc":"Stops the service used by store display PCs.","tier":2,"impact":1},{"id":"wmp-share","cat":"services","name":"Turn off Media Player network sharing","desc":"Stops Windows Media Player sharing your media library on the network.","tier":2,"impact":1},{"id":"insider","cat":"services","name":"Turn off the Windows Insider service","desc":"Only needed if you’re in the Windows Insider Program.","tier":2,"impact":1},{"id":"geolocation","cat":"services","name":"Turn off the location service","desc":"Stops the service that provides your location to apps. Weather, maps and Find my device lose it.","tier":2,"impact":1},{"id":"ics","cat":"services","name":"Turn off Internet Connection Sharing","desc":"Stops sharing this PC’s connection with other devices. Hyper-V’s default network switch also uses it.","tier":2,"impact":1},{"id":"phone-svc","cat":"services","name":"Turn off the Phone service","desc":"Manages telephony state for calls through Phone Link.","tier":2,"impact":1},{"id":"telephony","cat":"services","name":"Turn off Telephony","desc":"Old telephony support used by dial-up and some VPN software.","tier":2,"impact":1},{"id":"smart-card","cat":"services","name":"Turn off smart card services","desc":"Stops smart card readers, certificate propagation and smart card policy. Leave on if you use a security key in smart card mode.","tier":2,"impact":1},{"id":"payments-nfc","cat":"services","name":"Turn off Payments and NFC","desc":"Stops the Payments and NFC/SE Manager service. Desktops rarely have NFC.","tier":2,"impact":1},{"id":"wallet","cat":"services","name":"Turn off the Wallet service","desc":"Stops the service behind Microsoft Wallet.","tier":2,"impact":1},{"id":"alljoyn","cat":"services","name":"Turn off AllJoyn Router","desc":"An old smart-home device protocol that almost nothing uses anymore.","tier":2,"impact":1},{"id":"lltd","cat":"services","name":"Turn off the network map service","desc":"Stops Link-Layer Topology Discovery, which draws the network map in old Control Panel pages.","tier":2,"impact":1},{"id":"iscsi","cat":"services","name":"Turn off iSCSI Initiator","desc":"Only used to connect to network storage over iSCSI.","tier":2,"impact":1},{"id":"snmp-trap","cat":"services","name":"Turn off SNMP Trap","desc":"Receives network management messages on business networks.","tier":2,"impact":1},{"id":"webdav","cat":"services","name":"Turn off WebDAV client","desc":"Used to open some cloud and web folders as drives.","tier":2,"impact":1},{"id":"branchcache","cat":"services","name":"Turn off BranchCache","desc":"A business feature that caches content from office servers.","tier":2,"impact":1},{"id":"offline-files","cat":"services","name":"Turn off Offline Files","desc":"Keeps copies of network-share files on this PC. Business networks only.","tier":2,"impact":1},{"id":"work-folders","cat":"services","name":"Turn off Work Folders","desc":"Syncs files from a workplace server.","tier":2,"impact":1},{"id":"rec-troubleshoot","cat":"services","name":"Turn off recommended troubleshooting","desc":"Stops Windows running troubleshooters on its own. You can still run them from Settings.","tier":2,"impact":1},{"id":"diag-exec","cat":"services","name":"Turn off Diagnostic Execution service","desc":"Runs diagnostic actions for troubleshooting.","tier":2,"impact":1},{"id":"wdi-hosts","cat":"services","name":"Turn off diagnostic host services","desc":"The service and system hosts that run Windows diagnostics.","tier":2,"impact":1},{"id":"problem-reports","cat":"services","name":"Turn off problem report support","desc":"Supports the Problem Reports control panel.","tier":2,"impact":1},{"id":"mixed-reality","cat":"services","name":"Turn off Mixed Reality services","desc":"Windows Mixed Reality, spatial audio for it and spatial data. Leave on if you use a Windows Mixed Reality headset.","tier":2,"impact":1},{"id":"perception-sim","cat":"services","name":"Turn off Perception Simulation","desc":"A developer tool that simulates mixed-reality input.","tier":2,"impact":1},{"id":"mobile-hotspot","cat":"services","name":"Turn off Mobile Hotspot","desc":"Stops sharing this PC’s connection over Wi-Fi.","tier":2,"impact":1},{"id":"wifi-direct","cat":"services","name":"Turn off Wi-Fi Direct services","desc":"Used for wireless displays (Miracast) and some printers.","tier":2,"impact":1},{"id":"sensors","cat":"services","name":"Turn off sensor services","desc":"Orientation, light and other sensors. Laptops and tablets use them for auto-rotate and auto-brightness.","tier":2,"impact":1},{"id":"bluetooth","cat":"services","name":"Turn off Bluetooth","desc":"Stops Bluetooth support. Bluetooth headsets, controllers and mice stop working.","tier":2,"impact":1},{"id":"wia","cat":"services","name":"Turn off Windows Image Acquisition","desc":"Used by scanners and some older cameras.","tier":2,"impact":1},{"id":"messaging","cat":"services","name":"Turn off the Messaging service","desc":"Text message sync used by phone features.","tier":2,"impact":1},{"id":"contact-index","cat":"services","name":"Turn off contact indexing","desc":"Indexes contacts for fast search in Mail and People.","tier":2,"impact":1},{"id":"sync-host","cat":"services","name":"Turn off Sync Host","desc":"Syncs mail, contacts and calendar for the built-in Mail and Calendar apps.","tier":2,"impact":1},{"id":"edge-update-manual","cat":"services","name":"Start Edge’s updater only when needed","desc":"Edge still updates — its scheduled tasks start the updater when it’s time.","tier":2,"impact":1},{"id":"google-update-manual","cat":"services","name":"Start Google’s updater only when needed","desc":"Chrome still updates through its scheduled tasks. Does nothing if Chrome isn’t installed.","tier":2,"impact":1},{"id":"adobe-update-manual","cat":"services","name":"Start Adobe’s updater only when needed","desc":"Stops the Acrobat update service running all the time. Does nothing if Acrobat isn’t installed.","tier":2,"impact":1},{"id":"nv-telemetry","cat":"services","name":"Turn off NVIDIA telemetry container","desc":"Older NVIDIA drivers ran a separate telemetry service. Newer drivers don’t have it.","tier":2,"impact":1},{"id":"rdp-services","cat":"services","name":"Turn off Remote Desktop host services","desc":"Only needed to connect to this PC with Remote Desktop.","tier":2,"impact":1},{"id":"winrm","cat":"services","name":"Turn off Windows Remote Management","desc":"Lets administrators run commands on this PC remotely.","tier":2,"impact":1},{"id":"netbios-helper","cat":"services","name":"Turn off NetBIOS helper","desc":"Supports old-style network names. Some older network drives and printers need it.","tier":2,"impact":1},{"id":"sms-router","cat":"services","name":"Turn off SMS Router","desc":"Routes text messages for phone features.","tier":2,"impact":1},{"id":"dynamic-lock","cat":"services","name":"Turn off Natural Authentication","desc":"Powers Dynamic Lock, which locks the PC when your phone walks away.","tier":2,"impact":1},{"id":"event-collector","cat":"services","name":"Turn off Windows Event Collector","desc":"Collects event logs from other PCs on business networks.","tier":2,"impact":1},{"id":"push-to-install","cat":"services","name":"Turn off Push to Install","desc":"Lets the Microsoft Store install apps sent from the web or another device.","tier":2,"impact":1},{"id":"cellular-time","cat":"services","name":"Turn off cellular time","desc":"Sets the clock from a mobile network. Desktops don’t have one.","tier":2,"impact":1},{"id":"wwan","cat":"services","name":"Turn off mobile broadband","desc":"Only needed for built-in 4G/5G modems.","tier":2,"impact":1},{"id":"esim","cat":"services","name":"Turn off eSIM profile assistant","desc":"Manages eSIM profiles for cellular modems.","tier":2,"impact":1},{"id":"hyperv-guest","cat":"services","name":"Turn off Hyper-V guest services","desc":"These only do something when Windows runs inside a Hyper-V virtual machine.","tier":2,"impact":1},{"id":"embedded-mode","cat":"services","name":"Turn off Embedded Mode","desc":"Used by single-purpose devices running Windows IoT.","tier":2,"impact":1},{"id":"kiosk","cat":"services","name":"Turn off Assigned Access","desc":"Runs kiosk-mode PCs that are locked to one app.","tier":2,"impact":1},{"id":"infrared","cat":"services","name":"Turn off infrared monitor","desc":"Infrared file transfer, which modern PCs don’t have.","tier":2,"impact":1},{"id":"diag-hub","cat":"services","name":"Turn off the diagnostics hub collector","desc":"Collects profiling data for Visual Studio and other developer tools.","tier":2,"impact":1},{"id":"activex-installer","cat":"services","name":"Turn off ActiveX Installer","desc":"Installs ActiveX controls for old Internet Explorer pages.","tier":2,"impact":1},{"id":"file-history","cat":"services","name":"Turn off File History","desc":"Backs up your files to another drive. Leave on if you use File History.","tier":2,"impact":1},{"id":"windows-backup","cat":"services","name":"Turn off Windows Backup service","desc":"The old Backup and Restore (Windows 7) feature.","tier":2,"impact":1},{"id":"wps-connect","cat":"services","name":"Turn off Windows Connect Now","desc":"Sets up Wi-Fi with the WPS button on old routers.","tier":2,"impact":1},{"id":"svc-biometrics","cat":"services","name":"Turn off the biometric service","desc":"Stops the Windows Biometric Service. Turn this off only if you don’t sign in with a fingerprint or face.","tier":2,"impact":1},{"id":"svc-user-data","cat":"services","name":"Turn off contact and mail storage","desc":"Stops the User Data Storage and Access services behind the built-in Mail, Calendar and People apps. Leave on if you use them.","tier":2,"impact":1},{"id":"svc-peer-net","cat":"services","name":"Turn off peer networking","desc":"Stops the Peer Name Resolution and Peer-to-Peer Grouping services. Used by a few legacy HomeGroup-era features almost nothing needs today.","tier":2,"impact":1},{"id":"svc-camera-frame","cat":"services","name":"Turn off the camera frame server","desc":"Stops Windows Camera Frame Server, which lets apps share one webcam. Turn off only if you don’t use a webcam; it can stop the camera working in some apps.","tier":2,"impact":1},{"id":"svc-family","cat":"services","name":"Turn off Family Safety monitoring","desc":"Stops the Parental Controls monitor service. Safe to turn off on a PC with no child accounts.","tier":2,"impact":1},{"id":"svc-remote-registry","cat":"services","name":"Keep Remote Registry off","desc":"Makes sure the Remote Registry service (which lets other PCs edit this one’s registry) stays disabled. Usually already off.","tier":2,"impact":1},{"id":"svc-dusm","cat":"services","name":"Turn off the data-usage service","desc":"Stops the Data Usage service that tracks per-app network use. Pairs with the network data-usage driver tweak.","tier":2,"impact":1},{"id":"svc-appv","cat":"services","name":"Keep App-V client off","desc":"Keeps the Application Virtualization client (an enterprise feature) disabled. Usually already off.","tier":2,"impact":1},{"id":"svc-uev","cat":"services","name":"Keep UE-V agent off","desc":"Keeps the User Experience Virtualization agent (an enterprise roaming feature) disabled. Usually already off.","tier":2,"impact":1},{"id":"ceip-tasks","cat":"tasks","name":"Stop Customer Experience tasks","desc":"Disables the scheduled tasks that collect and send Customer Experience Improvement Program data.","tier":2,"impact":1},{"id":"feedback-tasks","cat":"tasks","name":"Stop feedback data tasks","desc":"Disables the scheduled tasks that send Feedback Hub data.","tier":2,"impact":1},{"id":"diskdiag-task","cat":"tasks","name":"Stop disk diagnostic data collection","desc":"Disables the task that gathers disk information for Microsoft.","tier":2,"impact":1},{"id":"maps-tasks","cat":"tasks","name":"Stop offline map update tasks","desc":"Disables the scheduled tasks that check for offline map updates.","tier":2,"impact":1},{"id":"task-offline-files","cat":"tasks","name":"Stop Offline Files sync tasks","desc":"Stops the scheduled Offline Files sync at sign-in and in the background. Only used for network folders made available offline.","tier":2,"impact":1},{"id":"task-setting-sync","cat":"tasks","name":"Stop settings sync upload tasks","desc":"Stops the tasks that upload your Windows settings to your Microsoft account in the background and when your network changes.","tier":2,"impact":1},{"id":"task-backup-notify","cat":"tasks","name":"Stop the “set up backup” reminder task","desc":"Stops the task that reminds you to configure Backup and Restore (Windows 7).","tier":2,"impact":1},{"id":"task-push-install","cat":"tasks","name":"Stop Push to Install tasks","desc":"Stops the tasks that register this PC for remote installs, so Store apps you pick on the web or another device don’t install here by themselves.","tier":2,"impact":1},{"id":"task-startup-app","cat":"tasks","name":"Stop the startup app impact scan","desc":"Disables the task that measures how much your startup apps slow sign-in.","tier":2,"impact":1},{"id":"task-pca-patch","cat":"tasks","name":"Stop compatibility database patching","desc":"Disables the Program Compatibility Assistant database update task.","tier":2,"impact":1},{"id":"task-mare-backup","cat":"tasks","name":"Stop the MareBackup telemetry task","desc":"Disables a compatibility telemetry task that runs alongside the Appraiser.","tier":2,"impact":1},{"id":"task-appraiser-exp","cat":"tasks","name":"Stop the newer Compatibility Appraiser task","desc":"Disables the “Exp” version of the Compatibility Appraiser added in recent builds.","tier":2,"impact":1},{"id":"task-autochk","cat":"tasks","name":"Stop the Autochk data task","desc":"Disables a task that collects disk-check data for the Customer Experience Program.","tier":2,"impact":1},{"id":"task-kernel-ceip","cat":"tasks","name":"Stop kernel CEIP data collection","desc":"Disables the kernel Customer Experience data task on builds that have it.","tier":2,"impact":1},{"id":"task-cloud-exp","cat":"tasks","name":"Stop the cloud experience task","desc":"Disables a task that sets up cloud-driven Windows experiences.","tier":2,"impact":1},{"id":"task-disk-footprint","cat":"tasks","name":"Stop disk footprint diagnostics","desc":"Disables a task that measures disk usage for diagnostics.","tier":2,"impact":1},{"id":"task-device-info","cat":"tasks","name":"Stop device information collection","desc":"Disables the tasks that gather device information for Microsoft.","tier":2,"impact":1},{"id":"task-feature-usage","cat":"tasks","name":"Stop feature usage reporting","desc":"Disables the tasks that report which Windows features you use.","tier":2,"impact":1},{"id":"task-onesettings","cat":"tasks","name":"Stop the OneSettings refresh task","desc":"Disables the task that downloads configuration changes from Microsoft.","tier":2,"impact":1},{"id":"task-location","cat":"tasks","name":"Stop location notification tasks","desc":"Disables the tasks that show “your location was used” notifications.","tier":2,"impact":1},{"id":"task-winsat","cat":"tasks","name":"Stop the WinSAT benchmark","desc":"Disables the task that benchmarks your hardware during maintenance.","tier":2,"impact":1},{"id":"task-net-trace","cat":"tasks","name":"Stop network info gathering","desc":"Disables a task that collects network information for diagnostics.","tier":2,"impact":1},{"id":"task-sqm","cat":"tasks","name":"Stop SQM data tasks","desc":"Disables the Software Quality Metrics task.","tier":2,"impact":1},{"id":"task-power-diag","cat":"tasks","name":"Stop power efficiency diagnostics","desc":"Disables the task that analyzes your power settings in the background.","tier":2,"impact":1},{"id":"task-retail-demo","cat":"tasks","name":"Stop the retail demo cleanup task","desc":"Only used on store display PCs.","tier":2,"impact":1},{"id":"task-wdi","cat":"tasks","name":"Stop the diagnostics resolution task","desc":"Disables a task that acts on Windows diagnostics results.","tier":2,"impact":1},{"id":"task-diagnosis","cat":"tasks","name":"Stop scheduled diagnostics","desc":"Disables scheduled diagnostics and the recommended troubleshooting scanner.","tier":2,"impact":1},{"id":"task-speech-model","cat":"tasks","name":"Stop speech model downloads","desc":"Disables the task that downloads speech recognition updates.","tier":2,"impact":1},{"id":"task-office-telemetry","cat":"tasks","name":"Stop Office telemetry tasks","desc":"Disables the Office telemetry agent tasks. Does nothing if Office isn’t installed.","tier":2,"impact":1},{"id":"task-file-history","cat":"tasks","name":"Stop File History maintenance","desc":"Disables File History’s maintenance task. Leave on if you use File History.","tier":2,"impact":1},{"id":"task-input-sync","cat":"tasks","name":"Stop input settings sync tasks","desc":"Disables the tasks that sync mouse, pen and touchpad settings with your account.","tier":2,"impact":1},{"id":"task-language-sync","cat":"tasks","name":"Stop language settings sync","desc":"Disables the task that syncs language settings with your account.","tier":2,"impact":1},{"id":"task-indexer-maint","cat":"tasks","name":"Stop search index maintenance","desc":"Disables the search indexer’s maintenance task. Leave on if you use Windows search for files.","tier":2,"impact":1},{"id":"task-error-details","cat":"tasks","name":"Stop error details updates","desc":"Disables the task that downloads error message details.","tier":2,"impact":1},{"id":"task-work-folders","cat":"tasks","name":"Stop Work Folders tasks","desc":"Only used when syncing with a workplace server.","tier":2,"impact":1},{"id":"task-workplace-join","cat":"tasks","name":"Stop automatic workplace join","desc":"Leave on if your PC is managed by work or school.","tier":2,"impact":1},{"id":"task-wwan","cat":"tasks","name":"Stop mobile broadband tasks","desc":"Only needed for built-in 4G/5G modems.","tier":2,"impact":1},{"id":"task-remote-assist","cat":"tasks","name":"Stop the Remote Assistance task","desc":"Disables Remote Assistance’s scheduled task.","tier":2,"impact":1},{"id":"task-media-sharing","cat":"tasks","name":"Stop media library sharing updates","desc":"Disables Windows Media Sharing’s library update task.","tier":2,"impact":1},{"id":"task-device-metadata","cat":"tasks","name":"Stop device metadata refresh","desc":"Disables the task that downloads pictures and info for your devices.","tier":2,"impact":1},{"id":"task-hello-cleanup","cat":"tasks","name":"Stop the Windows Hello face cleanup task","desc":"Removes face-recognition files when the feature isn’t used.","tier":2,"impact":1},{"id":"task-storage-spaces","cat":"tasks","name":"Stop Storage Spaces tasks","desc":"Only used with Storage Spaces drive pools.","tier":2,"impact":1},{"id":"task-sysmain","cat":"tasks","name":"Stop SysMain assessment tasks","desc":"Disables the prefetch database tasks that go with SysMain.","tier":2,"impact":1},{"id":"task-edu-print","cat":"tasks","name":"Stop education printer provisioning","desc":"Only used on school-managed PCs.","tier":2,"impact":1},{"id":"task-cellular","cat":"tasks","name":"Stop cellular provisioning","desc":"Sets up mobile network profiles on PCs with a modem.","tier":2,"impact":1},{"id":"task-aitagent","cat":"tasks","name":"Stop the old telemetry agent","desc":"Disables the legacy Application Impact Telemetry agent task (does nothing on builds that no longer have it).","tier":2,"impact":1},{"id":"task-pca-wallpaper","cat":"tasks","name":"Stop the wallpaper app-detection scan","desc":"Disables the Windows 11 task that scans for apps based on your wallpaper for the Program Compatibility Assistant.","tier":2,"impact":1},{"id":"task-ras-mobility","cat":"tasks","name":"Stop the dial-up/VPN mobility task","desc":"Disables the Remote Access Connection Manager mobility task. Not needed if you don’t use dial-up or auto-triggered VPNs.","tier":2,"impact":1},{"id":"task-printer-cleanup","cat":"tasks","name":"Stop the printer cleanup task","desc":"Disables the scheduled task that cleans up printer entries. Harmless to turn off on a PC that doesn’t print.","tier":2,"impact":1},{"id":"task-language","cat":"tasks","name":"Stop language-pack maintenance","desc":"Disables background language-component reconciliation and language-pack removal tasks. Your installed languages stay put.","tier":2,"impact":1},{"id":"task-family","cat":"tasks","name":"Stop Family Safety tasks","desc":"Disables the Family Safety monitor and refresh tasks. Safe on a PC with no child accounts.","tier":2,"impact":1},{"id":"task-temp-state","cat":"tasks","name":"Stop the app temp-state cleanup","desc":"Disables the periodic cleanup of temporary app state. The Deep clean on the Tools page handles this on demand instead.","tier":2,"impact":1},{"id":"task-data-integrity","cat":"tasks","name":"Stop data-integrity scans","desc":"Disables the periodic ReFS/Storage Spaces data-integrity scans, which normal NTFS drives don’t use.","tier":2,"impact":1},{"id":"task-dusm","cat":"tasks","name":"Stop the data-usage task","desc":"Disables the scheduled data-usage task that goes with the data-usage service.","tier":2,"impact":1},{"id":"task-memory-diag","cat":"tasks","name":"Stop scheduled memory diagnostics","desc":"Disables the background memory-diagnostic tasks. You can still run the Windows Memory Diagnostic by hand.","tier":2,"impact":1},{"id":"task-wof","cat":"tasks","name":"Stop Compact OS hash checks","desc":"Disables the Windows Overlay Filter hash-management tasks used by Compact OS on heavily compressed installs.","tier":2,"impact":1},{"id":"diagtrack","cat":"privacy","name":"Turn off the telemetry service","desc":"Stops Connected User Experiences and Telemetry collecting and uploading usage data in the background.","tier":0,"impact":1},{"id":"diagtrack-logger","cat":"privacy","name":"Turn off the telemetry boot logger","desc":"Stops the trace session that records telemetry events from the moment Windows starts.","tier":1,"impact":1},{"id":"telemetry-level","cat":"privacy","name":"Send only required diagnostic data","desc":"Sets Windows diagnostic data to Required, the lowest level on Home and Pro.","tier":1,"impact":1},{"id":"limit-diag-logs","cat":"privacy","name":"Limit diagnostic logs and crash dumps","desc":"If optional diagnostic data is turned on, stops Windows also sending extra diagnostic logs and full memory dumps. No effect at the Required level.","tier":1,"impact":1},{"id":"feedback-notif-policy","cat":"privacy","name":"Block feedback notifications","desc":"Stops Windows showing “give us feedback” notifications, by policy.","tier":1,"impact":1},{"id":"dmwappush","cat":"privacy","name":"Turn off the WAP push service","desc":"Disables a telemetry-related message routing service. Leave it on if work or school manages your PC.","tier":1,"impact":1},{"id":"wer","cat":"privacy","name":"Turn off error reporting","desc":"Stops Windows Error Reporting collecting crash dumps and uploading them after an app crashes.","tier":1,"impact":1},{"id":"ceip-policy","cat":"privacy","name":"Opt out of the Customer Experience Program","desc":"Turns off the Customer Experience Improvement Program by policy.","tier":1,"impact":1},{"id":"appcompat-telemetry-off","cat":"privacy","name":"Turn off app compatibility telemetry","desc":"Stops the Application Telemetry engine and the program inventory collector.","tier":1,"impact":1},{"id":"activity-history","cat":"privacy","name":"Turn off activity history","desc":"Stops Windows recording the apps and files you use.","tier":1,"impact":1},{"id":"ad-id","cat":"privacy","name":"Turn off the advertising ID","desc":"Stops apps using a per-user ID to show you targeted ads.","tier":1,"impact":1},{"id":"ad-id-policy","cat":"privacy","name":"Block the advertising ID for every account","desc":"Turns off the advertising ID by policy, so new accounts and updates can’t turn it back on.","tier":1,"impact":1},{"id":"tailored","cat":"privacy","name":"Turn off tailored experiences","desc":"Stops Microsoft using diagnostic data to personalize tips and ads.","tier":1,"impact":1},{"id":"tailored-policy","cat":"privacy","name":"Block tailored experiences by policy","desc":"Locks tailored experiences off with a policy, so a Windows update can’t switch them back on.","tier":1,"impact":1},{"id":"search-history-device","cat":"privacy","name":"Don’t keep search history on this PC","desc":"Stops Windows search remembering what you searched for.","tier":1,"impact":1},{"id":"search-cloud-user","cat":"privacy","name":"Don’t search your Microsoft account content","desc":"Turns off cloud content search for your personal and work accounts in Windows search.","tier":1,"impact":1},{"id":"clipboard-history","cat":"privacy","name":"Turn off clipboard history","desc":"Stops Windows keeping a list of everything you copy. Win + V stops showing past items.","tier":1,"impact":1},{"id":"feedback-freq","cat":"privacy","name":"Never ask for feedback","desc":"Stops Windows feedback prompts.","tier":1,"impact":1},{"id":"typing-insights","cat":"privacy","name":"Turn off typing insights","desc":"Stops Windows collecting statistics about how you type.","tier":1,"impact":1},{"id":"inking-typing","cat":"privacy","name":"Turn off inking and typing personalization","desc":"Stops Windows building a personal dictionary from what you type and write, and harvesting your contacts for it.","tier":1,"impact":1},{"id":"handwriting-data","cat":"privacy","name":"Stop sharing handwriting data","desc":"Stops handwriting samples and recognition error reports being sent to Microsoft.","tier":1,"impact":1},{"id":"online-speech","cat":"privacy","name":"Turn off online speech recognition","desc":"Stops your voice being sent to Microsoft for recognition. Voice typing (Win + H) stops working.","tier":1,"impact":1},{"id":"voice-activation","cat":"privacy","name":"Turn off voice activation for apps","desc":"Stops voice assistants listening for a wake word in the background.","tier":1,"impact":1},{"id":"lang-list","cat":"privacy","name":"Don’t share your language list with websites","desc":"Stops websites seeing every language installed on your PC.","tier":1,"impact":1},{"id":"app-launch-tracking","cat":"privacy","name":"Turn off app launch tracking","desc":"Stops Windows tracking which apps you open. Start loses its “Most used” list.","tier":1,"impact":1},{"id":"app-diagnostics","cat":"privacy","name":"Block apps reading info about your other apps","desc":"Turns off app diagnostic access, so Store apps can’t see which other apps are running.","tier":1,"impact":1},{"id":"cortana-off","cat":"privacy","name":"Turn off Cortana","desc":"Turns off Cortana by policy on builds that still include it.","tier":1,"impact":1},{"id":"cloud-search","cat":"privacy","name":"Keep search away from your cloud accounts","desc":"Stops Windows search pulling results from OneDrive, Outlook and other signed-in cloud accounts.","tier":1,"impact":1},{"id":"search-location","cat":"privacy","name":"Don’t let search use your location","desc":"Stops Windows search sending your location with queries.","tier":1,"impact":1},{"id":"web-search-policy","cat":"privacy","name":"Block web results in Windows search","desc":"Reinforces local-only search with a policy, so updates can’t add web results back.","tier":1,"impact":1},{"id":"clipboard-cloud","cat":"privacy","name":"Don’t sync your clipboard to the cloud","desc":"Stops clipboard contents syncing across your devices through your Microsoft account. Local clipboard history still works.","tier":1,"impact":1},{"id":"nearby-share","cat":"privacy","name":"Turn off Nearby sharing","desc":"Turns off Nearby sharing and sharing across your devices, so this PC stops advertising itself to nearby devices. You can’t send files to nearby PCs any more.","tier":1,"impact":1},{"id":"message-sync","cat":"privacy","name":"Don’t back up text messages to the cloud","desc":"Stops message sync used by older Phone and Messaging features.","tier":1,"impact":1},{"id":"lockscreen-camera","cat":"privacy","name":"Turn off the camera on the lock screen","desc":"Stops the camera being opened from the lock screen without signing in.","tier":1,"impact":1},{"id":"lockscreen-toasts","cat":"privacy","name":"Hide notifications on the lock screen","desc":"Stops message previews and other notifications appearing before you sign in.","tier":1,"impact":1},{"id":"remote-assistance","cat":"privacy","name":"Turn off Remote Assistance","desc":"Stops anyone being invited to view or control your PC through Windows Remote Assistance — a feature often abused in tech-support scams.","tier":1,"impact":1},{"id":"edge-telemetry","cat":"privacy","name":"Limit Microsoft Edge data collection","desc":"Turns off optional diagnostic data and browsing-based personalization in Edge.","tier":1,"impact":1},{"id":"office-telemetry-off","cat":"privacy","name":"Turn off Microsoft Office telemetry","desc":"Turns off the Office telemetry modules in Office 2016 and later (including Microsoft 365 apps). Does nothing if Office isn’t installed.","tier":1,"impact":1},{"id":"location-off","cat":"privacy","name":"Turn off location services","desc":"Turns off Windows location for every app. Weather, maps, automatic time zone and Find my device stop knowing where you are.","tier":1,"impact":1},{"id":"settings-sync","cat":"privacy","name":"Stop syncing settings to your Microsoft account","desc":"Keeps themes, passwords and preferences on this PC only. Other PCs signed in to your account stop picking them up.","tier":1,"impact":1},{"id":"onesettings-downloads","cat":"privacy","name":"Block OneSettings configuration downloads","desc":"Stops Windows regularly downloading remote configuration from Microsoft’s OneSettings service. Some diagnostic and feature settings then stay at their built-in values.","tier":1,"impact":1},{"id":"linguistic-data","cat":"privacy","name":"Stop sending inking and typing data","desc":"Blocks the “Improve inking and typing” option, so samples of what you type and write aren’t sent to Microsoft.","tier":1,"impact":1},{"id":"cloud-optimized-content","cat":"privacy","name":"Turn off cloud-optimized content","desc":"Windows uses its built-in defaults instead of content Microsoft pushes from the cloud, such as extra promoted taskbar and Start shortcuts.","tier":1,"impact":1},{"id":"account-state-content","cat":"privacy","name":"Turn off Microsoft account promotions","desc":"Stops Windows showing cloud-driven Microsoft account and subscription content, such as backup and storage upsells in Start and Settings.","tier":1,"impact":1},{"id":"spotlight-desktop-policy","cat":"privacy","name":"Turn off Windows Spotlight on the desktop","desc":"Removes the Spotlight wallpaper option and its “Learn about this picture” desktop icon, which fetch images and links from Microsoft.","tier":1,"impact":1},{"id":"settings-online-tips","cat":"privacy","name":"Turn off online tips in Settings","desc":"Stops the Settings app downloading tips and help videos from Microsoft. Settings opens without the online help panel.","tier":1,"impact":1},{"id":"phone-link-policy","cat":"privacy","name":"Block linking a phone to this PC","desc":"Stops this PC linking to Android phones or iPhones, and removes it from any phone it was linked to. Phone Link can’t connect.","tier":1,"impact":1},{"id":"cross-device-policy","cat":"privacy","name":"Turn off cross-device experiences","desc":"Hides this PC from your other Windows devices, so “continue on PC” and sharing between your devices stop working.","tier":1,"impact":1},{"id":"location-scripting","cat":"privacy","name":"Turn off location scripting","desc":"Stops scripts using the Windows location provider to find out where this PC is.","tier":1,"impact":1},{"id":"wer-no-extra-data","cat":"privacy","name":"Send less data with crash reports","desc":"If Windows sends an error report, it can’t include extra files or memory contents that Microsoft asks for afterwards.","tier":1,"impact":1},{"id":"kms-avs","cat":"privacy","name":"Don’t send KMS activation data","desc":"Stops Windows automatically sending activation data to Microsoft when it activates through a company KMS server. It has no effect on normal retail activation.","tier":1,"impact":1},{"id":"maps-settings-traffic","cat":"privacy","name":"Stop the Offline Maps page going online","desc":"Stops the Offline Maps page in Settings connecting to Microsoft just because you opened it.","tier":1,"impact":1},{"id":"wmp-metadata-off","cat":"privacy","name":"Stop Windows Media Player looking up media info","desc":"Windows Media Player stops sending details of your CDs, DVDs and music files to the internet to fetch album art, titles and radio presets.","tier":1,"impact":1},{"id":"wmp-first-run","cat":"privacy","name":"Skip Windows Media Player’s first-run setup","desc":"Hides the privacy and setup dialogs the classic Windows Media Player shows the first time it opens.","tier":1,"impact":1},{"id":"policy-perm-diag","cat":"privacy","name":"Block app diagnostic info by policy","desc":"Stops every Store app reading diagnostic information about your other apps, for all accounts.","tier":1,"impact":1},{"id":"policy-perm-motion","cat":"privacy","name":"Block motion data for all apps by policy","desc":"Denies every Store app access to motion and activity sensor data, for all accounts.","tier":1,"impact":1},{"id":"policy-perm-trusted","cat":"privacy","name":"Block trusted devices for all apps by policy","desc":"Stops every Store app using devices already paired to this PC on its own, for all accounts.","tier":1,"impact":1},{"id":"policy-perm-voice-lock","cat":"privacy","name":"Block voice activation on the lock screen","desc":"Stops apps responding to voice commands while the PC is locked.","tier":1,"impact":1},{"id":"edge-search-suggest","cat":"privacy","name":"Turn off Edge address-bar suggestions","desc":"Stops Edge sending what you type in the address bar to the search engine as you type. You get no live search suggestions.","tier":1,"impact":1},{"id":"edge-error-pages","cat":"privacy","name":"Turn off Edge’s similar-page suggestions","desc":"When a site can’t be reached, Edge no longer asks a Microsoft web service for similar pages to suggest.","tier":1,"impact":1},{"id":"edge-payment-query","cat":"privacy","name":"Stop sites checking for saved payment methods in Edge","desc":"Websites can no longer ask Edge whether you have payment cards saved.","tier":1,"impact":1},{"id":"edge-implicit-signin","cat":"privacy","name":"Stop Edge signing in automatically","desc":"Edge no longer signs in to your Microsoft account by itself just because Windows uses it. You can still sign in by hand.","tier":1,"impact":1},{"id":"edge-3p-cookies","cat":"privacy","name":"Block third-party cookies in Edge","desc":"Stops ad and tracking cookies from other sites following you around the web. A few sites’ embedded sign-ins and comment boxes may stop working.","tier":1,"impact":1},{"id":"chrome-metrics","cat":"privacy","name":"Turn off Chrome usage statistics","desc":"Stops Google Chrome sending usage statistics and crash reports to Google.","tier":1,"impact":1},{"id":"chrome-url-data","cat":"privacy","name":"Stop Chrome sending the pages you visit","desc":"Turns off Chrome’s “Make searches and browsing better” option, which sends the addresses of pages you visit to Google.","tier":1,"impact":1},{"id":"chrome-feedback","cat":"privacy","name":"Turn off Chrome feedback","desc":"Removes Chrome’s “Send feedback” option, which can attach screenshots and page details.","tier":1,"impact":1},{"id":"chrome-3p-cookies","cat":"privacy","name":"Block third-party cookies in Chrome","desc":"Stops ad and tracking cookies from other sites following you around the web in Chrome. A few sites’ embedded sign-ins and comment boxes may stop working.","tier":1,"impact":1},{"id":"firefox-telemetry","cat":"privacy","name":"Turn off Firefox telemetry and studies","desc":"Stops Mozilla Firefox uploading usage data and taking part in Mozilla’s feature experiments.","tier":1,"impact":1},{"id":"office-diag-neither","cat":"privacy","name":"Send no Office diagnostic data","desc":"Sets Microsoft 365 apps to the documented “Neither” level, so no diagnostic data about Office is sent to Microsoft.","tier":1,"impact":1},{"id":"office-optional-connected","cat":"privacy","name":"Turn off optional connected experiences in Office","desc":"Turns off extras such as LinkedIn features, 3D Maps and the online weather in Outlook that send data to Microsoft. Core Office features keep working.","tier":1,"impact":1},{"id":"office-content-analysis","cat":"privacy","name":"Stop Office sending your content for analysis","desc":"Turns off Office features that send your document content to Microsoft, such as Designer, Editor’s cloud checks and Translator.","tier":1,"impact":1},{"id":"office-feedback","cat":"privacy","name":"Turn off Office feedback","desc":"Removes the feedback button and “Send a smile” options from Office apps.","tier":1,"impact":1},{"id":"office-ceip","cat":"privacy","name":"Opt Office out of the Customer Experience Program","desc":"Stops Office collecting usage data for Microsoft’s Customer Experience Improvement Program.","tier":1,"impact":1},{"id":"perm-location","cat":"privacy","name":"Block app access to your location","desc":"Denies Microsoft Store apps your location. Weather and Maps lose it.","tier":1,"impact":1},{"id":"perm-webcam","cat":"privacy","name":"Block app access to the camera","desc":"Denies Store apps your webcam. Can stop the camera in Store apps like the Camera app; desktop apps such as Discord and OBS are unaffected.","tier":1,"impact":1},{"id":"perm-mic","cat":"privacy","name":"Block app access to the microphone","desc":"Denies Store apps your microphone. Desktop apps like Discord aren’t affected, but Store voice apps are.","tier":1,"impact":1},{"id":"perm-notify-listen","cat":"privacy","name":"Block apps reading your notifications","desc":"Stops apps accessing your notifications.","tier":1,"impact":1},{"id":"perm-calendar","cat":"privacy","name":"Block app access to your calendar","desc":"Denies Store apps your calendar.","tier":1,"impact":1},{"id":"perm-contacts","cat":"privacy","name":"Block app access to your contacts","desc":"Denies Store apps your contacts.","tier":1,"impact":1},{"id":"perm-callhistory","cat":"privacy","name":"Block app access to call history","desc":"Denies Store apps your call history.","tier":1,"impact":1},{"id":"perm-email","cat":"privacy","name":"Block app access to email","desc":"Denies Store apps access to email.","tier":1,"impact":1},{"id":"perm-tasks","cat":"privacy","name":"Block app access to tasks","desc":"Denies Store apps your tasks.","tier":1,"impact":1},{"id":"perm-messaging","cat":"privacy","name":"Block app access to messages","desc":"Denies Store apps your text messages.","tier":1,"impact":1},{"id":"perm-radios","cat":"privacy","name":"Block apps controlling radios","desc":"Stops apps turning Bluetooth and other radios on and off.","tier":1,"impact":1},{"id":"perm-bluetooth-sync","cat":"privacy","name":"Block unpaired Bluetooth communication","desc":"Stops apps exchanging data with unpaired Bluetooth devices.","tier":1,"impact":1},{"id":"perm-documents","cat":"privacy","name":"Block app access to Documents","desc":"Denies Store apps your Documents folder.","tier":1,"impact":1},{"id":"perm-pictures","cat":"privacy","name":"Block app access to Pictures","desc":"Denies Store apps your Pictures folder.","tier":1,"impact":1},{"id":"perm-videos","cat":"privacy","name":"Block app access to Videos","desc":"Denies Store apps your Videos folder.","tier":1,"impact":1},{"id":"perm-filesystem","cat":"privacy","name":"Block broad file-system access","desc":"Stops Store apps accessing your whole file system.","tier":1,"impact":1},{"id":"perm-account-info","cat":"privacy","name":"Block app access to account info","desc":"Denies Store apps your name, picture and other account info.","tier":1,"impact":1},{"id":"perm-cellular","cat":"privacy","name":"Block app access to cellular data","desc":"Denies Store apps your cellular connection.","tier":1,"impact":1},{"id":"perm-eyetracking","cat":"privacy","name":"Block app access to eye tracking","desc":"Denies apps your eye-tracking device.","tier":1,"impact":1},{"id":"perm-phone","cat":"privacy","name":"Block apps making phone calls","desc":"Stops apps placing calls through a paired phone.","tier":1,"impact":1},{"id":"edge-dnt","cat":"privacy","name":"Send Do Not Track from Edge","desc":"Turns on the Do Not Track request for every site in Edge.","tier":1,"impact":1},{"id":"consumer-features-off","cat":"privacy","name":"Stop auto-installed promoted apps","desc":"Blocks Windows from silently installing promoted third-party apps (the “Consumer Experiences” that drop games and app shortcuts into Start).","tier":1,"impact":1},{"id":"spotlight-features-off","cat":"privacy","name":"Turn off Windows Spotlight features","desc":"Turns off Windows Spotlight: the rotating lock-screen and desktop pictures, and the tips and suggestions that come with them. Enterprise and Education editions follow it fully; others may ignore parts of it.","tier":1,"impact":1},{"id":"font-providers","cat":"privacy","name":"Stop downloading fonts online","desc":"Turns off the online font provider, so Windows doesn’t contact Microsoft to fetch fonts.","tier":1,"impact":1},{"id":"mrt-report","cat":"privacy","name":"Stop Malicious Removal Tool reports","desc":"Stops the monthly Malicious Software Removal Tool sending infection reports to Microsoft. It still runs.","tier":1,"impact":1},{"id":"wmdrm-online","cat":"privacy","name":"Block Windows Media DRM internet access","desc":"Stops the media DRM component contacting the internet for licenses and metadata.","tier":1,"impact":1},{"id":"findmydevice","cat":"privacy","name":"Turn off Find my device","desc":"Stops Windows reporting your device location for the Find my device feature.","tier":1,"impact":1},{"id":"disable-onedrive","cat":"privacy","name":"Turn off OneDrive sync","desc":"Blocks OneDrive file sync with a policy. Only turn this off if you don’t use OneDrive.","tier":1,"impact":1},{"id":"wu-no-auto-reboot","cat":"updates","name":"Never restart automatically while you’re signed in","desc":"Asks Windows Update to wait for you to restart instead of rebooting on its own while you’re signed in. Restart deadlines can still override it on newer builds.","tier":1,"impact":2},{"id":"wu-restart-notify","cat":"updates","name":"Tell me when a restart is needed","desc":"Shows a notification when an update needs a restart, so you can pick the moment.","tier":1,"impact":1},{"id":"wu-latest-asap","cat":"updates","name":"Don’t get preview features as soon as they’re out","desc":"Turns off “Get the latest updates as soon as they’re available”, so new features arrive with the regular, better-tested rollout.","tier":1,"impact":1},{"id":"wu-no-drivers","cat":"updates","name":"Don’t install drivers through Windows Update","desc":"Stops Windows Update replacing drivers — most often an older graphics driver over the one you installed. You’ll need to update drivers yourself.","tier":1,"impact":1},{"id":"maps-autoupdate","cat":"updates","name":"Don’t update offline maps automatically","desc":"Stops Windows downloading offline map updates in the background.","tier":1,"impact":1},{"id":"wu-bg-bandwidth","cat":"updates","name":"Limit background update downloads to 10%","desc":"Caps how much of your connection Windows Update and Store downloads can use in the background, so a big update doesn’t cause lag spikes mid-match.","tier":0,"impact":2},{"id":"wu-active-hours","cat":"updates","name":"Protect 8 AM to 2 AM from update restarts","desc":"Sets Windows Update active hours to 8 AM–2 AM, the longest window allowed, so Windows won’t restart for updates during it. Updates still download and install as usual.","tier":1,"impact":1},{"id":"wu-quiet-notifications","cat":"updates","name":"Hide update pop-ups except restart warnings","desc":"Windows Update stops showing notifications about available or installing updates, but still warns you before a restart. Updates keep installing; check Settings to see what’s pending.","tier":1,"impact":1},{"id":"bing-search","cat":"explorer","name":"Keep Start search local","desc":"Removes web results from Start search, so it’s faster and what you type isn’t sent to Bing.","tier":1,"impact":1},{"id":"search-highlights","cat":"explorer","name":"Turn off search highlights","desc":"Removes the daily illustrations and trending searches from the search box and search window.","tier":0,"impact":1},{"id":"start-suggestions","cat":"explorer","name":"Turn off Start menu suggestions","desc":"Removes suggested and promoted apps from Start.","tier":0,"impact":1},{"id":"silent-installs","cat":"explorer","name":"Stop automatic app installs","desc":"Stops Windows quietly installing promoted apps and games.","tier":1,"impact":1},{"id":"tips","cat":"explorer","name":"Turn off tips and suggestions","desc":"Stops “Get tips and suggestions” notifications.","tier":0,"impact":1},{"id":"settings-suggestions","cat":"explorer","name":"Turn off suggested content in Settings","desc":"Removes promotions and suggestions from the Settings app.","tier":0,"impact":1},{"id":"lockscreen-tips","cat":"explorer","name":"Turn off lock screen tips and fun facts","desc":"Removes the tips, tricks and ads drawn over the lock screen picture.","tier":0,"impact":1},{"id":"welcome-experience","cat":"explorer","name":"Skip the “what’s new” screen after updates","desc":"Stops the Windows welcome experience appearing after feature updates.","tier":1,"impact":1},{"id":"finish-setup-nag","cat":"explorer","name":"Stop “finish setting up your device” prompts","desc":"Removes the full-screen prompts asking you to set up Microsoft 365, OneDrive backup and Phone Link.","tier":1,"impact":1},{"id":"explorer-ads","cat":"explorer","name":"Turn off OneDrive ads in File Explorer","desc":"Removes sync-provider notifications — mostly OneDrive offers — from File Explorer.","tier":0,"impact":1},{"id":"start-iris","cat":"explorer","name":"Turn off Start recommendations for tips and apps","desc":"Removes tips, shortcuts and new-app promotions from the Recommended section of Start.","tier":1,"impact":1},{"id":"start-account-notif","cat":"explorer","name":"Turn off account notifications in Start","desc":"Removes Microsoft account and backup nags from the Start menu profile button.","tier":1,"impact":1},{"id":"start-recent-docs","cat":"explorer","name":"Don’t show recent files in Start and jump lists","desc":"Stops Start, jump lists and File Explorer listing files you opened recently.","tier":1,"impact":1},{"id":"start-more-pins","cat":"explorer","name":"More pins in Start","desc":"Uses the Start layout with more pinned apps and fewer recommendations.","tier":1,"impact":1},{"id":"file-ext","cat":"explorer","name":"Show file extensions","desc":"Shows the .exe, .pdf or .zip at the end of file names — the easiest way to spot a fake “document” that’s really a program.","tier":1,"impact":1},{"id":"hidden-files","cat":"explorer","name":"Show hidden files","desc":"Shows hidden files and folders such as AppData in File Explorer.","tier":1,"impact":1},{"id":"launch-this-pc","cat":"explorer","name":"Open File Explorer to This PC","desc":"File Explorer opens on your drives instead of Home or Quick access.","tier":1,"impact":1},{"id":"quick-access-recent","cat":"explorer","name":"Don’t show recent and frequent files in Explorer","desc":"Keeps your recently opened files and folders out of Home and Quick access.","tier":1,"impact":1},{"id":"classic-menu","cat":"explorer","name":"Classic right-click menu","desc":"Brings back the full Windows 10 right-click menu, so you don’t have to click “Show more options”.","tier":1,"impact":1},{"id":"end-task","cat":"explorer","name":"End task from the taskbar","desc":"Adds “End task” when you right-click an app on the taskbar — the fastest way to close a frozen game.","tier":1,"impact":1},{"id":"taskbar-small","cat":"explorer","name":"Slim taskbar","desc":"Smaller taskbar icons and a thinner bar; the clock shows just the time.","tier":1,"impact":1},{"id":"taskbar-left","cat":"explorer","name":"Align the taskbar to the left","desc":"Puts Start and taskbar icons on the left like Windows 10.","tier":1,"impact":1},{"id":"taskview-button","cat":"explorer","name":"Hide the Task View button","desc":"Removes the Task View button from the taskbar. Win + Tab still works.","tier":1,"impact":1},{"id":"chat-button","cat":"explorer","name":"Hide the Chat button","desc":"Removes the Teams Chat button from the taskbar on builds that have it.","tier":1,"impact":1},{"id":"copilot-button","cat":"explorer","name":"Hide the Copilot button","desc":"Removes the Copilot button from the taskbar on builds that have it.","tier":1,"impact":1},{"id":"search-hide","cat":"explorer","name":"Hide taskbar search","desc":"Removes the search box and icon from the taskbar. Ego OS uses the Open-Shell menu for search instead; Win + S still opens Windows search.","tier":1,"impact":1},{"id":"meet-now","cat":"explorer","name":"Hide Meet Now","desc":"Removes the Meet Now camera icon from the Windows 10 taskbar.","tier":1,"impact":1},{"id":"people-bar","cat":"explorer","name":"Hide People on the taskbar","desc":"Removes the People button from the Windows 10 taskbar.","tier":1,"impact":1},{"id":"clock-seconds","cat":"explorer","name":"Show seconds in the taskbar clock","desc":"Adds seconds to the clock. Uses a tiny bit more power.","tier":1,"impact":1},{"id":"aero-shake","cat":"explorer","name":"Turn off shake to minimize","desc":"Stops a quick shake of a window title bar minimizing every other window.","tier":1,"impact":1},{"id":"snap-flyout","cat":"explorer","name":"Turn off the snap layout pop-up","desc":"Stops snap layouts appearing when you hover the maximize button.","tier":1,"impact":1},{"id":"compact-explorer","cat":"explorer","name":"Compact File Explorer view","desc":"Reduces the spacing between items in File Explorer so more fits on screen.","tier":1,"impact":1},{"id":"nav-expand","cat":"explorer","name":"Expand the folder tree to the open folder","desc":"File Explorer’s navigation pane follows you to the folder you’re in.","tier":1,"impact":1},{"id":"full-path-title","cat":"explorer","name":"Show the full path in File Explorer","desc":"Shows the full folder path in the File Explorer title.","tier":1,"impact":1},{"id":"explorer-separate","cat":"explorer","name":"Open folders in a separate process","desc":"Runs File Explorer windows apart from the taskbar, so a crashing folder window doesn’t take the taskbar with it. Uses a little more memory.","tier":1,"impact":1},{"id":"shortcut-suffix","cat":"explorer","name":"Drop “ - Shortcut” from new shortcuts","desc":"New shortcuts are named after their target without the “ - Shortcut” ending.","tier":1,"impact":1},{"id":"numlock-boot","cat":"explorer","name":"Num Lock on at startup","desc":"Turns Num Lock on at the sign-in screen and when you sign in.","tier":1,"impact":1},{"id":"verbose-status","cat":"explorer","name":"Detailed startup and shutdown messages","desc":"Shows what Windows is doing while it starts and shuts down, instead of just “Please wait”. Handy when shutdown hangs.","tier":1,"impact":1},{"id":"logon-blur","cat":"explorer","name":"Sharp sign-in background","desc":"Removes the blur from the sign-in screen background.","tier":1,"impact":1},{"id":"pen-suggestions","cat":"explorer","name":"Turn off pen workspace app suggestions","desc":"Stops app promotions in the pen and Windows Ink menu.","tier":1,"impact":1},{"id":"start-recent-apps","cat":"explorer","name":"Hide recently added apps in Start","desc":"Removes the “Recently added” list from the Start menu.","tier":1,"impact":1},{"id":"taskbar-badges","cat":"explorer","name":"Hide taskbar badges","desc":"Removes unread counters and other badges from taskbar icons.","tier":1,"impact":1},{"id":"alttab-windows","cat":"explorer","name":"Alt + Tab shows windows only","desc":"Stops Alt + Tab filling up with Edge browser tabs, so switching back to your game is one press.","tier":1,"impact":1},{"id":"desktop-thispc","cat":"explorer","name":"Show This PC on the desktop","desc":"Adds the This PC icon to the desktop.","tier":1,"impact":1},{"id":"restore-folders","cat":"explorer","name":"Reopen folder windows after restart","desc":"File Explorer windows you had open come back when you sign in.","tier":1,"impact":1},{"id":"snap-assist-off","cat":"explorer","name":"Turn off Snap Assist suggestions","desc":"After you snap a window to one side, Windows no longer fills the other side with your open windows to pick from.","tier":1,"impact":1},{"id":"snap-bar-off","cat":"explorer","name":"Turn off snap layouts at the top of the screen","desc":"Dragging a window to the top edge no longer drops down the snap layouts bar. Snapping to the sides still works.","tier":1,"impact":1},{"id":"snap-fill-off","cat":"explorer","name":"Don’t resize snapped windows to fill space","desc":"When you snap a window, Windows keeps its width instead of stretching it to fill the space next to another snapped window.","tier":1,"impact":1},{"id":"snap-off","cat":"explorer","name":"Turn off window snapping","desc":"Dragging a window to a screen edge or corner no longer snaps or maximizes it, and snap layouts are switched off.","tier":1,"impact":1},{"id":"explorer-status-bar-off","cat":"explorer","name":"Hide the File Explorer status bar","desc":"Removes the bar at the bottom of File Explorer that shows how many items are in a folder and how many are selected.","tier":1,"impact":1},{"id":"info-tips-off","cat":"explorer","name":"Turn off hover descriptions","desc":"Hovering over files, folders and desktop icons no longer pops up a tooltip with their type, size and date.","tier":1,"impact":1},{"id":"folder-size-tips-off","cat":"explorer","name":"Don’t show folder sizes in hover tips","desc":"Folder tooltips stop listing size and contents, so File Explorer doesn’t scan a folder just because the mouse passed over it. Helps on slow or network drives.","tier":1,"impact":1},{"id":"preview-handlers-off","cat":"explorer","name":"Turn off preview pane handlers","desc":"The preview pane stops loading documents, PDFs and other files through their apps’ preview add-ins. It shows a plain icon instead.","tier":1,"impact":1},{"id":"item-checkboxes","cat":"explorer","name":"Use check boxes to select files","desc":"Adds a check box to each file and folder in File Explorer so you can select several without holding Ctrl.","tier":1,"impact":1},{"id":"show-empty-drives","cat":"explorer","name":"Show empty drives","desc":"Card readers and optical drives with nothing in them still appear in This PC instead of being hidden.","tier":1,"impact":1},{"id":"show-merge-conflicts","cat":"explorer","name":"Ask before merging folders","desc":"When you copy a folder onto one with the same name, File Explorer asks whether to merge them instead of merging silently.","tier":1,"impact":1},{"id":"drive-letters-first","cat":"explorer","name":"Show drive letters before drive names","desc":"This PC lists drives as “(C:) Windows” instead of “Windows (C:)”, which makes them easier to tell apart at a glance.","tier":1,"impact":1},{"id":"nav-all-folders","cat":"explorer","name":"Show all folders in the navigation pane","desc":"The left pane of File Explorer shows the full folder tree, including your user folder and Control Panel, like older versions of Windows.","tier":1,"impact":1},{"id":"office-files-home-off","cat":"explorer","name":"Don’t show Office.com files in File Explorer","desc":"File Explorer Home stops listing recent and recommended files from your Microsoft account, and stops fetching that list online.","tier":1,"impact":1},{"id":"explorer-gallery-off","cat":"explorer","name":"Hide Gallery in File Explorer","desc":"Removes the Gallery entry from the File Explorer navigation pane. Your Pictures folder is unchanged.","tier":1,"impact":1},{"id":"cortana-button","cat":"explorer","name":"Hide the Cortana button","desc":"Removes the Cortana circle button from the Windows 10 taskbar.","tier":1,"impact":1},{"id":"show-desktop-corner-off","cat":"explorer","name":"Turn off the show desktop corner","desc":"Clicking the far right corner of the taskbar no longer minimizes every window. Win + D still shows the desktop.","tier":1,"impact":1},{"id":"taskbar-main-display","cat":"explorer","name":"Show the taskbar on the main display only","desc":"With more than one monitor, only the main display gets a taskbar, so a game or video on a second screen isn’t framed by one.","tier":1,"impact":1},{"id":"taskbar-flashing-off","cat":"explorer","name":"Stop taskbar buttons flashing","desc":"Apps that want attention, such as chat apps, no longer flash their taskbar button.","tier":1,"impact":1},{"id":"tray-show-all","cat":"explorer","name":"Always show all tray icons","desc":"Every notification area icon stays visible on the taskbar instead of being tucked behind the up arrow.","tier":1,"impact":1},{"id":"spotlight-desktop-icon","cat":"explorer","name":"Hide the “Learn about this picture” icon","desc":"Removes the desktop icon that Windows Spotlight adds when it chooses your wallpaper. The wallpaper keeps changing as before.","tier":1,"impact":1},{"id":"new-app-alert-off","cat":"explorer","name":"Stop “new app can open this file” pop-ups","desc":"Windows no longer interrupts to say a newly installed app can open a file type. Your default apps don’t change.","tier":1,"impact":1},{"id":"store-openwith-off","cat":"explorer","name":"Remove “Look for an app in the Store”","desc":"The “Open with” dialog stops offering to search the Microsoft Store for an app when you open an unknown file type.","tier":1,"impact":1},{"id":"taskbar-combine","cat":"explorer","name":"Never combine taskbar buttons","desc":"Shows a separate labelled button for every open window on the taskbar instead of stacking them (Windows 10, and Windows 11 23H2 and later).","tier":1,"impact":1},{"id":"copy-details","cat":"explorer","name":"Detailed file-copy dialog by default","desc":"Opens the file-copy window with the speed graph and details already expanded.","tier":1,"impact":1},{"id":"no-lock-screen","cat":"explorer","name":"Skip the lock screen","desc":"Goes straight to the sign-in box instead of showing the lock-screen image first.","tier":1,"impact":1},{"id":"hide-fast-switching","cat":"explorer","name":"Hide Switch user","desc":"Removes the “Switch user” option. Useful on a single-user gaming PC.","tier":1,"impact":1},{"id":"transparency","cat":"visuals","name":"Turn off transparency effects","desc":"Removes the blur behind the taskbar, Start and windows, freeing a little GPU time on low-end hardware.","tier":1,"impact":1},{"id":"min-animate","cat":"visuals","name":"Turn off window animations","desc":"Windows open, close, minimize and maximize instantly.","tier":1,"impact":1},{"id":"taskbar-anim","cat":"visuals","name":"Turn off taskbar animations","desc":"Taskbar buttons and thumbnails appear without animating.","tier":1,"impact":1},{"id":"aero-peek","cat":"visuals","name":"Turn off Peek","desc":"Stops the full-size window preview that appears when you hover a taskbar thumbnail.","tier":1,"impact":1},{"id":"menu-delay","cat":"visuals","name":"Instant menus","desc":"Removes the 400 ms pause before submenus open.","tier":1,"impact":1},{"id":"drag-windows","cat":"visuals","name":"Drag window outlines","desc":"Drags an outline instead of redrawing the whole window, which is lighter on weak GPUs.","tier":1,"impact":1},{"id":"listview-alpha","cat":"visuals","name":"Turn off the translucent selection box","desc":"Uses a plain outline when you drag-select files.","tier":1,"impact":1},{"id":"icon-shadows","cat":"visuals","name":"Turn off desktop icon shadows","desc":"Removes drop shadows from desktop icon labels.","tier":1,"impact":1},{"id":"thumbnails","cat":"visuals","name":"Show icons instead of thumbnails","desc":"Folders full of images and videos open faster in File Explorer.","tier":1,"impact":1},{"id":"hover-time","cat":"visuals","name":"Faster hover previews","desc":"Taskbar previews and tooltips appear after 100 ms instead of 400 ms.","tier":1,"impact":1},{"id":"ego-wallpaper","cat":"visuals","name":"Ego OS wallpaper","desc":"Sets the black Ego OS wallpaper. Turning it off puts your old wallpaper back.","tier":1,"impact":1},{"id":"ego-signin","cat":"visuals","name":"Ego OS sign-in screen","desc":"Puts the Ego OS picture on the lock and sign-in screen: the dial round your name and password box. Turning it off puts the old one back.","tier":1,"impact":1},{"id":"ego-accent","cat":"visuals","name":"Ego OS dark accent","desc":"Uses a near-black accent colour on Start, the taskbar and title bars, and stops Windows picking an accent from the wallpaper.","tier":1,"impact":1},{"id":"dark-mode","cat":"visuals","name":"Dark mode everywhere","desc":"Switches Windows and apps that follow it to dark mode.","tier":1,"impact":1},{"id":"wallpaper-quality","cat":"visuals","name":"Full-quality wallpaper","desc":"Stops Windows recompressing JPEG wallpapers to 85% quality.","tier":1,"impact":1},{"id":"scrollbars-always","cat":"visuals","name":"Always show scrollbars","desc":"Keeps full-size scrollbars visible in Settings and Store apps instead of thin bars that only appear when you hover.","tier":1,"impact":1},{"id":"thumb-app-overlay-off","cat":"visuals","name":"Hide the app icon on thumbnails","desc":"File Explorer stops drawing the small app icon in the corner of picture and video thumbnails.","tier":1,"impact":1},{"id":"compressed-color-off","cat":"visuals","name":"Don’t color compressed and encrypted files","desc":"File Explorer shows NTFS-compressed and encrypted files in normal black text instead of blue or green.","tier":1,"impact":1},{"id":"first-logon-anim-off","cat":"visuals","name":"Skip the first sign-in animation","desc":"New accounts go straight to the desktop instead of the “Hi” and “We’re getting things ready” screens the first time they sign in.","tier":1,"impact":1},{"id":"signin-picture-off","cat":"visuals","name":"Plain sign-in screen background","desc":"The sign-in screen shows a solid accent color instead of the lock screen picture.","tier":1,"impact":1},{"id":"audio-ducking","cat":"audio","name":"Don’t lower game volume during voice calls","desc":"Stops Windows turning other sounds down by 80% when it detects a call — the reason games go quiet when Discord or a call starts.","tier":1,"impact":2},{"id":"notifications-off","cat":"audio","name":"Turn off notifications","desc":"No pop-up notifications from apps or Windows, so nothing slides in over a game. Turn this off again to get them back.","tier":1,"impact":1},{"id":"notification-sounds","cat":"audio","name":"Mute notification sounds","desc":"Notifications still appear, silently.","tier":1,"impact":1},{"id":"startup-sound-off","cat":"audio","name":"Turn off the startup sound","desc":"Windows starts silently.","tier":1,"impact":1},{"id":"notif-suggestions-off","cat":"audio","name":"Turn off notification suggestions","desc":"Windows stops popping up suggestions to turn off banners for apps whose notifications you tend to ignore.","tier":0,"impact":1},{"id":"system-beep-off","cat":"audio","name":"Turn off the system beep","desc":"Silences the basic warning beep that console windows and older programs play, such as pressing Backspace on an empty command line. Normal Windows sounds are unaffected.","tier":1,"impact":1},{"id":"notification-center-off","cat":"audio","name":"Remove the notification center","desc":"Removes the notification center (Action Center on Windows 10), so missed notifications can’t be reviewed later. On Windows 11 clicking the clock no longer opens the calendar either. Pop-up banners still appear.","tier":1,"impact":1},{"id":"ntfs-lastaccess","cat":"storage","name":"Stop last-access timestamp writes","desc":"Stops NTFS writing a timestamp every time a file is read. Fewer disk writes, most noticeable on hard drives.","tier":1,"impact":1},{"id":"ntfs-8dot3","cat":"storage","name":"Stop creating 8.3 short file names","desc":"Stops NTFS creating an extra DOS-style name for every new file, which speeds up folders with thousands of files. Existing files keep theirs.","tier":1,"impact":1},{"id":"thumb-cache-keep","cat":"storage","name":"Stop Windows deleting the thumbnail cache","desc":"Keeps picture and video thumbnails between cleanups, so big folders don’t have to rebuild them.","tier":1,"impact":1},{"id":"thumbs-db-network","cat":"storage","name":"No thumbnail files on network folders","desc":"Stops Windows writing hidden Thumbs.db files into shared network folders.","tier":1,"impact":1},{"id":"autoplay-off","cat":"storage","name":"Turn off AutoPlay","desc":"Stops Windows acting automatically when you plug in a USB drive or phone. Safer, and no pop-up over your game.","tier":1,"impact":1},{"id":"low-disk-warning","cat":"storage","name":"Turn off low disk space warnings","desc":"Stops the low disk space balloon. Keep an eye on free space yourself.","tier":1,"impact":1},{"id":"ntfs-memory-usage","cat":"storage","name":"Give NTFS more cache memory","desc":"Lets NTFS keep larger internal caches, which helps when thousands of small files are opened and closed, like game installs and updates. Uses a little more kernel memory, so only on 16 GB or more.","tier":1,"impact":1},{"id":"trim-on","cat":"storage","name":"Keep TRIM on for SSDs","desc":"Sets the file-system policy so Windows always tells your SSD which blocks are free. TRIM is on by default; this only changes something if a tool or policy turned it off, which slows SSDs down over time.","tier":1,"impact":1},{"id":"long-paths","cat":"storage","name":"Allow file paths longer than 260 characters","desc":"Lets apps that support it work with very deep folders and long file names, which some mod managers and game installers need. Apps that don’t support it behave as before.","tier":1,"impact":1},{"id":"crash-dump-small","cat":"storage","name":"Save small crash dumps only","desc":"After a blue screen Windows saves a small minidump instead of a memory dump that can be several gigabytes. Saves disk space and writes faster; deep crash debugging gets harder.","tier":1,"impact":1},{"id":"do-cache-limit","cat":"storage","name":"Keep the update download cache small","desc":"Caps the Delivery Optimization cache of downloaded updates and Store apps at 5 GB and clears files after one day instead of three.","tier":1,"impact":1},{"id":"app-archiving-off","cat":"storage","name":"Stop Windows archiving apps you rarely use","desc":"Stops Windows removing the files of Store apps and games you haven’t opened in a while, which would have to be downloaded again the next time you launch them. Uses more disk space.","tier":1,"impact":1},{"id":"msi-restore-points-off","cat":"storage","name":"No restore points for every app install","desc":"Stops Windows Installer creating a System Restore point each time a .msi program is installed or removed, so those installs finish faster and use less disk. Restore points from updates and manual ones still work.","tier":1,"impact":1},{"id":"msi-patch-cache-off","cat":"storage","name":"Stop caching copies of patched program files","desc":"Windows Installer stops keeping backup copies of files it patches, which can use up to 10% of the drive. Removing a patch later may ask for the original installer.","tier":1,"impact":1},{"id":"shortcut-search-off","cat":"storage","name":"Don’t search the disk for broken shortcuts","desc":"When a shortcut’s target has moved, Windows no longer searches your drives or tracking data to find it, which can freeze Explorer for many seconds. You get the “shortcut is broken” prompt straight away.","tier":1,"impact":1},{"id":"network-thumbnails-off","cat":"storage","name":"Show icons instead of thumbnails on network folders","desc":"Explorer stops downloading files from network shares and NAS drives just to draw thumbnails, so those folders open much faster. Local folders keep their thumbnails.","tier":1,"impact":1},{"id":"storage-sense-off","cat":"storage","name":"Turn off Storage Sense","desc":"Stops Windows automatically deleting temporary files and old downloads on a schedule. Clean on your own terms from the Tools page.","tier":1,"impact":1}]};
